-- Vorrats-Aufgaben (rollend-10) in bestehende Flüge einfügen: 108 Aufgaben, 6 Einheiten, mit form und zaehlt (FT-S). Ein Aufruf, eine Transaktion.
select set_config('lock_timeout', '3s', true), set_config('statement_timeout', '60s', true);
do $einspielen$
declare e record; n int; vorher int; gesamt int := 0; fehler text[] := '{}';
begin
  if (select count(*) from pg_attribute where attrelid = 'schule.aufgabe'::regclass and attname in ('form', 'zaehlt') and not attisdropped) <> 2
     or position('x->>''form''' in pg_get_functiondef('schule.aufgaben_einfuegen(bigint, jsonb)'::regprocedure)) = 0 then
    raise exception 'Vorrats-Aufgaben: erst FT-S einspielen (Spalten form/zaehlt, aufgaben_einfuegen)'; end if;
  for e in select * from (values
    (8, 'abbildungen.aehnlichkeit', 640, 27, $auf$[{"l": "streckung", "t": "streckung", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Eine zentrische Streckung hat das Zentrum Z(1 | −2) und den Streckfaktor k = 3. Der Punkt P(6 | 2) wird abgebildet. Der Pfeil von Z nach P geht ① Einheiten nach rechts und ② Einheiten nach oben. Der Pfeil von Z zum Bildpunkt P' ist k-mal so lang: Er geht ③ Einheiten nach rechts und ④ Einheiten nach oben. Der Bildpunkt hat die Koordinaten P'(⑤ | ⑥).", "schablone": "① = □; ② = □; ③ = □; ④ = □; ⑤ = □; ⑥ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [5, 4, 15, 12, 16, 10]}, "h": "Der Bildpunkt liegt auf dem Strahl von Z durch P. Gemessen wird immer vom Zentrum Z aus, nicht vom Ursprung.", "w": "Pfeil ZP: (6 − 1 | 2 − (−2)) = (5 | 4). Pfeil ZP': 3 · (5 | 4) = (15 | 12). P' = Z + (15 | 12) = (1 + 15 | −2 + 12) = (16 | 10).", "form": "lueckenweg", "zaehlt": "nein", "r": 10641}, {"l": "streckung", "t": "streckung", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Eine zentrische Streckung hat das Zentrum Z(2 | 1). Sie bildet den Punkt P(5 | 3) auf den Punkt P'(14 | 9) ab. Welchen Streckfaktor k hat diese Streckung?"}, "o": {"wert": 4}, "h": "Vergleiche den Pfeil von Z nach P mit dem Pfeil von Z nach P'.", "w": "Pfeil ZP: (5 − 2 | 3 − 1) = (3 | 2). Pfeil ZP': (14 − 2 | 9 − 1) = (12 | 8). Es ist 12 : 3 = 4 und 8 : 2 = 4. Also k = 4. Probe: Z + 4 · (3 | 2) = (14 | 9).", "form": "umkehren", "zaehlt": "ja", "r": 10642}, {"l": "streckung", "t": "streckung", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Der Punkt P(4 | 3) wird zentrisch gestreckt, mit dem Zentrum Z(1 | 1) und dem Faktor k = 2. Kim berechnet den Bildpunkt P'. Zeile 1: Pfeil von Z nach P: (4 + 1 | 3 + 1) = (5 | 4). Zeile 2: Mit k = 2 wird der Pfeil zu (10 | 8). Zeile 3: Bildpunkt P' = Z + (10 | 8) = (1 + 10 | 1 + 8) = (11 | 9). In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Wie bekommt man den Pfeil von einem Punkt Z zu einem Punkt P?", "w": "Der Pfeil von Z nach P ist P − Z = (4 − 1 | 3 − 1) = (3 | 2). Dann ist ZP' = (6 | 4) und P' = (1 + 6 | 1 + 4) = (7 | 5). Der erste Fehler steht in Zeile 1: Kim hat addiert statt subtrahiert.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 10643}, {"l": "bildgerade", "t": "bildgerade", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Gerade g: y = 3x + 2 wird mit dem Zentrum O(0 | 0) und dem Faktor k = 5 gestreckt. Der Punkt A(0 | 2) liegt auf g. Sein Bildpunkt A' hat die y-Koordinate ①. Der Punkt B(1 | 5) liegt auf g. Sein Bildpunkt B' hat die y-Koordinate ②. Die Bildgerade g' geht durch A' und B'. Für x = 6 hat g' den y-Wert ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [10, 25, 28]}, "h": "Beide Koordinaten des Punktes werden mit dem Faktor multipliziert. Für die Bildgerade brauchst du die Steigung zwischen A' und B'.", "w": "A' = (0 | 10). B' = (5 | 25). Steigung von g': (25 − 10) : (5 − 0) = 3. g': y = 3x + 10. Für x = 6: 3 · 6 + 10 = 28.", "form": "lueckenweg", "zaehlt": "nein", "r": 10644}, {"l": "bildgerade", "t": "bildgerade", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Die Gerade g: y = 2x + 5 wird mit dem Zentrum O(0 | 0) und dem Faktor k = 3 gestreckt. Wie groß ist der y-Achsenabschnitt der Bildgeraden g'? Rechne auf zwei Wegen. Weg A: Strecke den Punkt (0 | 5) von g und lies den y-Achsenabschnitt ab. Weg B: Ein Punkt (x' | y') liegt genau dann auf g', wenn (x' : 3 | y' : 3) auf g liegt. Setze x = x' : 3 und y = y' : 3 in die Gleichung von g ein und löse nach y' auf."}, "o": {"wert": 15}, "h": "Was erhältst du, wenn du nach dem Einsetzen beide Seiten der Gleichung mit 3 multiplizierst?", "w": "Weg A: (0 | 5) wird zu (0 | 15), der Achsenabschnitt ist 15. Weg B: y' : 3 = 2 · (x' : 3) + 5. Mit 3 malnehmen: y' = 2x' + 15. Der y-Achsenabschnitt ist 15. Beide Wege: 15.", "form": "zwei_wege", "zaehlt": "ja", "r": 10645}, {"l": "bildgerade", "t": "bildgerade", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Die Gerade g: y = −x + 4 wird mit dem Zentrum O(0 | 0) und dem Faktor k = 2 gestreckt. Kim bestimmt die Bildgerade g'. Zeile 1: g hat die Steigung −1 und den y-Achsenabschnitt 4. Zeile 2: Die Streckung verdoppelt auch die Steigung: g' hat die Steigung −2. Zeile 3: Der y-Achsenabschnitt wird verdoppelt auf 8. Also ist g': y = −2x + 8. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Wie liegen eine Gerade und ihre Bildgerade zueinander, wenn das Zentrum nicht auf der Geraden liegt? Was folgt daraus für die Steigung?", "w": "Eine Gerade und ihre Bildgerade sind parallel, die Steigung bleibt −1. Nur der Achsenabschnitt wird verdoppelt. g': y = −x + 8. Der erste Fehler steht in Zeile 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 10646}, {"l": "schwerpunkt", "t": "schwerpunkt", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Dreieck hat die Eckpunkte A(1 | 2), B(8 | 3) und C(3 | 10). Die x-Koordinaten der drei Eckpunkte ergeben zusammen ①. Die y-Koordinaten ergeben zusammen ②. Der Schwerpunkt S hat die Koordinaten S(③ | ④).", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [12, 15, 4, 5]}, "h": "Der Schwerpunkt eines Dreiecks hat als Koordinaten den Mittelwert der drei x-Koordinaten und den Mittelwert der drei y-Koordinaten.", "w": "x: 1 + 8 + 3 = 12. y: 2 + 3 + 10 = 15. S = (12 : 3 | 15 : 3) = (4 | 5).", "form": "lueckenweg", "zaehlt": "nein", "r": 10647}, {"l": "schwerpunkt", "t": "schwerpunkt", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine dünne Platte besteht überall aus demselben Material mit gleicher Dichte und hat überall dieselbe Dicke. Sie hat die Form eines Dreiecks ABC mit A(0 | 0), B(12 | 0) und C(3 | 9). Die Maße sind in cm. Die Platte soll waagerecht auf einer Spitze balancieren. Wie weit ist der Auflagepunkt von der Seite AB entfernt? Gib den Abstand in cm an."}, "o": {"wert": 3, "einheit": "cm"}, "h": "Der Auflagepunkt ist der Schwerpunkt des Dreiecks. Gefragt ist nur sein Abstand von der Seite AB, also die y-Koordinate.", "w": "S = ((0 + 12 + 3) : 3 | (0 + 0 + 9) : 3) = (5 | 3). Die Seite AB liegt auf der x-Achse, der Abstand ist die y-Koordinate 3 cm.", "form": "anwenden", "zaehlt": "ja", "r": 10648}, {"l": "schwerpunkt", "t": "schwerpunkt", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Dreieck ABC hat die Eckpunkte A(0 | 0) und B(12 | 0). Sein Schwerpunkt ist S(8 | 3). Die Einheit im Koordinatensystem ist 1 cm. Wie lang ist die Seite AC in cm?"}, "o": {"wert": 15, "einheit": "cm"}, "h": "Zwei Dinge musst du nacheinander bestimmen: zuerst, wo C liegt, dann, wie weit C von A entfernt ist.", "w": "Für den Schwerpunkt gilt: x-Koordinate von S = (0 + 12 + x) : 3 = 8, also x = 12. y-Koordinate von S = (0 + 0 + y) : 3 = 3, also y = 9. C(12 | 9). AC² = 12² + 9² = 144 + 81 = 225, AC = 15 cm.", "form": "umkehren", "zaehlt": "ja", "r": 10649}, {"l": "aehnlich", "t": "aehnlich", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Das Dreieck B ist ähnlich zum Dreieck A. Das Dreieck A hat die Seiten 4 cm, 6 cm und 8 cm. Die kürzeste Seite von B ist 12 cm lang. Der Streckfaktor von A nach B ist ①. Die mittlere Seite von B ist ② cm lang, die längste Seite ③ cm. Der Umfang von B ist ④ cm.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [3, 18, 24, 54]}, "h": "Bei ähnlichen Dreiecken werden alle Seiten mit demselben Faktor vervielfacht. Vergleiche zuerst zwei entsprechende Seiten.", "w": "k = 12 : 4 = 3. Mittlere Seite: 6 · 3 = 18 cm. Längste Seite: 8 · 3 = 24 cm. Umfang: 12 + 18 + 24 = 54 cm.", "form": "lueckenweg", "zaehlt": "nein", "r": 10650}, {"l": "aehnlich", "t": "aehnlich", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt die Seitenlängen von drei Dreiecken, jeweils von der kürzesten zur längsten Seite. Welche zwei Dreiecke sind zueinander ähnlich?", "grafik": {"typ": "tabelle", "kopf": ["Dreieck", "kürzeste Seite", "mittlere Seite", "längste Seite"], "zeilen": [["A", "3 cm", "4 cm", "6 cm"], ["B", "6 cm", "8 cm", "9 cm"], ["C", "9 cm", "12 cm", "18 cm"]]}}, "a": ["A und C", "A und B", "B und C", "Alle drei Dreiecke"], "o": {"index": 0}, "h": "Teile für zwei Dreiecke jeweils entsprechende Seiten durcheinander. Alle drei Quotienten müssen gleich sein.", "w": "A → C: 9 : 3 = 3, 12 : 4 = 3, 18 : 6 = 3. Alle Quotienten sind gleich. A → B: 2, 2 und 1,5, also nicht ähnlich. B → C: 1,5, 1,5 und 2, also nicht ähnlich.", "form": "bruecke", "zaehlt": "ja", "r": 10651}, {"l": "aehnlich", "t": "aehnlich", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Das Dreieck B ist ähnlich zum Dreieck A. A hat die Seiten 4 cm, 6 cm und 8 cm. Die kürzeste Seite von B ist 12 cm lang. Kim berechnet die mittlere Seite von B und prüft sie. Zeile 1: Streckfaktor von A nach B: 12 : 4 = 3. Zeile 2: Mittlere Seite von B: 6 + 3 = 9 cm. Zeile 3: Damit ist das Verhältnis der mittleren Seiten von B und A gleich 9 : 6 = 1,5. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Wie wirkt ein Streckfaktor auf eine Seitenlänge: addieren oder multiplizieren?", "w": "Eine Seite wird mit dem Streckfaktor multipliziert: 6 · 3 = 18 cm. Kim hat 3 addiert. Außerdem müsste das Verhältnis der mittleren Seiten wieder 3 sein, nicht 1,5. Der erste Fehler steht in Zeile 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 10652}, {"l": "strahlensatz1", "t": "strahlensatz1", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Zwei Strahlen mit dem gemeinsamen Anfangspunkt S werden von zwei parallelen Geraden geschnitten, die nicht durch S gehen. Die erste Gerade schneidet die Strahlen in A und B, die zweite in A' und B'. A und A' liegen auf dem einen Strahl, B und B' auf dem anderen, A und B liegen näher bei S. Es gilt SA = 4 cm, SA' = 12 cm und SB = 5 cm. Das Verhältnis SA' : SA ist ①. Die Strecke SB' ist ② cm lang. Die Strecke BB' ist ③ cm lang.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [3, 15, 10]}, "h": "Nach dem 1. Strahlensatz haben die Verhältnisse SA' : SA und SB' : SB denselben Wert. BB' ist der Teil von SB', der nicht zu SB gehört.", "w": "SA' : SA = 12 : 4 = 3. SB' = 3 · 5 = 15 cm. BB' = SB' − SB = 15 − 5 = 10 cm.", "form": "lueckenweg", "zaehlt": "nein", "r": 10653}, {"l": "strahlensatz1", "t": "strahlensatz1", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Die Sonnenstrahlen sind zueinander parallel. Ein senkrechter Stab ist 1,5 m hoch und wirft auf dem waagerechten Boden einen 2 m langen Schatten. Im selben Moment wirft ein senkrechter Turm einen 28 m langen Schatten. Wie hoch ist der Turm?"}, "o": {"wert": 21, "einheit": "m"}, "h": "Stab mit Schatten und Turm mit Schatten bilden zwei Dreiecke mit demselben Verhältnis Höhe : Schattenlänge.", "w": "Höhe : Schatten ist beim Stab 1,5 : 2 = 0,75. Beim Turm gilt dasselbe Verhältnis: Höhe = 0,75 · 28 = 21 m.", "form": "anwenden", "zaehlt": "ja", "r": 10654}, {"l": "strahlensatz1", "t": "strahlensatz1", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Zwei Strahlen mit dem Anfangspunkt S werden von zwei parallelen Geraden geschnitten. Die erste schneidet in A und B, die zweite in A' und B'. A und A' liegen auf dem einen Strahl, B und B' auf dem anderen, A und B liegen näher bei S. Es gilt SA = 3 cm, SA' = 9 cm und SB = 4 cm. Kim berechnet die Strecke BB'. Zeile 1: 1. Strahlensatz: SA' : SA = SB' : SB, also 9 : 3 = SB' : 4. Zeile 2: Das Verhältnis 9 : 3 ist 3. Also ist SB' = 3 · 4 = 12 cm. Zeile 3: Dann ist BB' = SB' + SB = 12 + 4 = 16 cm. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "BB' ist ein Stück der Strecke SB'. Wie bekommt man dieses Stück?", "w": "SB' = SB + BB', also BB' = SB' − SB = 12 − 4 = 8 cm. Kim hat in Zeile 3 addiert. Zeile 1 und 2 sind richtig.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 10655}, {"l": "strahlensatz2", "t": "strahlensatz2", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Zwei Strahlen mit dem gemeinsamen Anfangspunkt S werden von zwei parallelen Geraden geschnitten, die nicht durch S gehen. Die erste Gerade schneidet die Strahlen in A und B, die zweite in A' und B'. A und A' liegen auf dem einen Strahl, B und B' auf dem anderen, A und B liegen näher bei S. Es gilt SA = 5 cm, SA' = 15 cm und AB = 4 cm. Nach dem 2. Strahlensatz ist das Verhältnis A'B' : AB so groß wie SA' : SA. Dieses Verhältnis ist ①. Die Strecke A'B' ist ② cm lang. Sie ist um ③ cm länger als AB.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [3, 12, 8]}, "h": "Das Verhältnis der Strecken auf den Strahlen ist so groß wie das Verhältnis der Parallelstrecken A'B' und AB.", "w": "SA' : SA = 15 : 5 = 3. A'B' = 3 · 4 = 12 cm. Unterschied: 12 − 4 = 8 cm.", "form": "lueckenweg", "zaehlt": "nein", "r": 10656}, {"l": "strahlensatz2", "t": "strahlensatz2", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Zwei Strahlen mit dem Anfangspunkt S werden von zwei parallelen Geraden geschnitten. Die erste schneidet in A und B, die zweite in A' und B'. A und A' liegen auf dem einen Strahl, B und B' auf dem anderen, A liegt zwischen S und A'. Es gilt A'B' : AB = 5 : 2 und SA = 8 cm. Wie lang ist die Strecke AA'?"}, "o": {"wert": 12, "einheit": "cm"}, "h": "Zuerst brauchst du SA'. Dann ist AA' das Stück von SA', das nicht zu SA gehört.", "w": "Nach dem 2. Strahlensatz ist SA' : SA = A'B' : AB = 5 : 2. Also SA' = 8 · 5 : 2 = 20 cm. AA' = SA' − SA = 20 − 8 = 12 cm.", "form": "umkehren", "zaehlt": "ja", "r": 10657}, {"l": "strahlensatz2", "t": "strahlensatz2", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Zwei Strahlen mit dem Anfangspunkt S werden von zwei parallelen Geraden geschnitten. Die erste schneidet in A und B, die zweite in A' und B'. A und A' liegen auf dem einen Strahl, B und B' auf dem anderen. Es gilt SA = 5 cm, SA' = 8 cm und AB = 10 cm. Kim berechnet A'B'. Zeile 1: 2. Strahlensatz: A'B' : AB = SA : SA'. Zeile 2: Also A'B' : 10 = 5 : 8 und A'B' = 10 · 5 : 8 = 6,25 cm. Zeile 3: A'B' ist also kürzer als AB. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "A' liegt weiter von S entfernt als A. Wird die Parallelstrecke dann länger oder kürzer?", "w": "Es gilt A'B' : AB = SA' : SA = 8 : 5. Also A'B' = 10 · 8 : 5 = 16 cm. Zeile 1 hat die Verhältnisse vertauscht, die Folgezeilen rechnen daraus richtig weiter.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 10658}, {"l": "flaeche_volumen", "t": "flaeche_volumen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Zwei Würfel sind zueinander ähnlich. Der kleine Würfel hat die Kantenlänge 2 cm und das Volumen 8 Kubikzentimeter. Der große Würfel hat die Kantenlänge 6 cm. Der Streckfaktor von klein nach groß ist ①. Die Oberfläche wird mit dem Faktor ② vervielfacht, das Volumen mit dem Faktor ③. Das Volumen des großen Würfels ist ④ Kubikzentimeter.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [3, 9, 27, 216]}, "h": "Längen werden mit k vervielfacht. Für Flächen und Rauminhalte gilt eine andere Regel: Zähle die Richtungen, in denen gestreckt wird.", "w": "k = 6 : 2 = 3. Flächenfaktor 3² = 9. Volumenfaktor 3³ = 27. Volumen: 8 · 27 = 216 cm³. Probe: 6 · 6 · 6 = 216.", "form": "lueckenweg", "zaehlt": "nein", "r": 10659}, {"l": "flaeche_volumen", "t": "flaeche_volumen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein kleines Dreieck hat die Grundseite 4 cm und den Flächeninhalt 12 cm². Ein dazu ähnliches großes Dreieck hat die Grundseite 10 cm. Diese Seite entspricht der 4-cm-Seite des kleinen Dreiecks. Wie groß ist der Flächeninhalt des großen Dreiecks in cm²? Rechne auf zwei Wegen. Weg A: mit dem Streckfaktor der Längen und dem Flächenfaktor. Weg B: berechne die Höhe des kleinen Dreiecks, dann die Höhe des großen Dreiecks, dann seine Fläche."}, "o": {"wert": 75, "einheit": "cm²"}, "h": "Beide Wege müssen dasselbe ergeben. Der Streckfaktor der Längen ist 10 : 4.", "w": "Weg A: k = 10 : 4 = 2,5. Flächenfaktor 2,5² = 6,25. Fläche: 12 · 6,25 = 75 cm². Weg B: Höhe klein: 2 · 12 : 4 = 6 cm. Höhe groß: 6 · 2,5 = 15 cm. Fläche: 10 · 15 : 2 = 75 cm².", "form": "zwei_wege", "zaehlt": "ja", "r": 10660}, {"l": "flaeche_volumen", "t": "flaeche_volumen", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Modellboot ist eine genaue Verkleinerung eines echten Boots aus demselben Rumpfform-Entwurf. Das Modell ist 0,6 m lang, sein Rumpf fasst 4 Liter. Der Rumpf des echten Boots fasst 4 000 Liter. Wie lang ist das echte Boot in Metern?"}, "o": {"wert": 6, "einheit": "m"}, "h": "Wie oft passt das Fassungsvermögen des Modells in das des echten Boots? Was sagt dieser Faktor über die Längen aus?", "w": "Das Fassungsvermögen ist 4 000 : 4 = 1 000-mal so groß. Rauminhalte wachsen mit dem Faktor k³, also ist k³ = 1 000 und k = 10, denn 10 · 10 · 10 = 1 000. Länge des echten Boots: 0,6 · 10 = 6 m.", "form": "anwenden", "zaehlt": "ja", "r": 10661}, {"l": "anwendung", "t": "anwendung", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein rechteckiges Foto ist 9 cm breit und 6 cm hoch. Es wird zu einem ähnlichen Poster vergrößert, das 45 cm breit ist. Der Vergrößerungsfaktor ist ①. Das Poster ist ② cm hoch. Der Flächeninhalt des Posters ist ③ cm².", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [5, 30, 1350]}, "h": "Bei einer ähnlichen Vergrößerung werden Breite und Höhe mit demselben Faktor vervielfacht. Die Fläche rechnest du am Schluss aus den neuen Seiten.", "w": "k = 45 : 9 = 5. Höhe: 6 · 5 = 30 cm. Fläche: 45 · 30 = 1 350 cm².", "form": "lueckenweg", "zaehlt": "nein", "r": 10662}, {"l": "anwendung", "t": "anwendung", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Lochkamera ist ein Kasten mit einem winzigen Loch in der Vorderwand. Ein Baum, 1,8 m hoch, steht senkrecht 6 m vor dem Loch. Die Rückwand des Kastens ist 12 cm vom Loch entfernt. Der Baum erscheint auf der Rückwand als umgekehrtes Bild. Wie hoch ist dieses Bild in cm?"}, "o": {"wert": 3.6, "einheit": "cm"}, "h": "Die Lichtstrahlen laufen durch das Loch. Vor und hinter dem Loch entstehen zwei Dreiecke mit gleichem Verhältnis Höhe : Abstand. Rechne in einer Einheit.", "w": "Höhe : Abstand ist beim Baum 1,8 m : 6 m = 0,3. Beim Bild gilt dasselbe Verhältnis: Bildhöhe = 0,3 · 12 cm = 3,6 cm.", "form": "anwenden", "zaehlt": "ja", "r": 10663}, {"l": "anwendung", "t": "anwendung", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein senkrechter Stab ist 1,2 m hoch und wirft einen 0,8 m langen Schatten. Im selben Moment wirft eine senkrechte Fichte auf dem waagerechten Boden einen 10 m langen Schatten. Kim berechnet die Höhe der Fichte. Zeile 1: Beim Stab ist Höhe : Schatten = 1,2 : 0,8 = 1,5. Zeile 2: Bei der Fichte ist das Verhältnis Höhe : Schatten dasselbe, also 1,5. Zeile 3: Die Höhe der Fichte ist also 10 : 1,5 ≈ 6,7 m. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Prüfe jede Zeile nach. Bei Stab und Fichte ist das Verhältnis Höhe : Schatten gleich.", "w": "Höhe = Verhältnis · Schatten = 1,5 · 10 = 15 m. Kim hat geteilt statt malgenommen. Eine Fichte, die niedriger ist als ihr Schatten, passt auch nicht zu einem Stab, der höher ist als sein Schatten.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 10664}, {"l": "streckung_vektor", "t": "streckung_vektor", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Eine zentrische Streckung hat das Zentrum Z(2 | 1) und den Faktor k = −3. Der Punkt P(7 | 4) wird zu P' abgebildet. Der Vektor von Z nach P hat die Komponenten (5 | 3). Der Vektor von Z nach P' hat die Komponenten (① | ②). Der Bildpunkt hat die Koordinaten P'(③ | ④).", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [-15, -9, -13, -8]}, "h": "Der Vektor ZP' ist k-mal der Vektor ZP. Ein negativer Faktor dreht die Richtung um. Der Bildpunkt entsteht, wenn du den Vektor ZP' an Z anlegst.", "w": "ZP' = −3 · (5 | 3) = (−15 | −9). P' = Z + ZP' = (2 − 15 | 1 − 9) = (−13 | −8).", "form": "lueckenweg", "zaehlt": "nein", "r": 10665}, {"l": "streckung_vektor", "t": "streckung_vektor", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt, wie weit man von dem Zentrum Z der Streckung nach rechts und nach oben gehen muss, um zu P und zu dem Bildpunkt P' zu kommen. Negative Zahlen bedeuten nach links oder nach unten. Welche Aussage passt?", "grafik": {"typ": "tabelle", "kopf": ["", "nach rechts", "nach oben"], "zeilen": [["von Z zu P", "2", "1"], ["von Z zu P'", "−4", "−2"]]}}, "a": ["Der Streckfaktor ist k = 2. P' liegt auf derselben Seite von Z wie P und doppelt so weit von Z entfernt.", "Der Streckfaktor ist k = −2. P' liegt auf derselben Seite von Z wie P.", "Der Streckfaktor ist k = −0,5. P' liegt auf der anderen Seite von Z und halb so weit von Z entfernt.", "Der Streckfaktor ist k = −2. P' liegt auf der anderen Seite von Z als P und doppelt so weit von Z entfernt."], "o": {"index": 3}, "h": "Vergleiche den Pfeil zu P' mit dem Pfeil zu P: Mit welcher Zahl wird jede Komponente vervielfacht?", "w": "Pfeil zu P: (2 | 1). Pfeil zu P': (−4 | −2) = −2 · (2 | 1). Also k = −2. Das Minuszeichen heißt: andere Seite von Z. Der Betrag 2 heißt: doppelt so weit entfernt.", "form": "bruecke", "zaehlt": "ja", "r": 10666}, {"l": "streckung_vektor", "t": "streckung_vektor", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine zentrische Streckung hat den Faktor k = −2. Sie bildet den Punkt P(7 | 3) auf den Punkt P'(−2 | −3) ab. Wie groß ist die x-Koordinate des Zentrums Z?"}, "o": {"wert": 4}, "h": "Das Bild P' entsteht durch Strecken von P vom Zentrum Z aus. Stelle für die x-Koordinaten eine Gleichung auf, in der die x-Koordinate von Z die Unbekannte ist.", "w": "Mit x für die x-Koordinate von Z: −2 = x + (−2) · (7 − x) = x − 14 + 2x = 3x − 14. Also 3x = 12 und x = 4. Probe: 4 + (−2) · (7 − 4) = 4 − 6 = −2.", "form": "umkehren", "zaehlt": "ja", "r": 10667}]$auf$::jsonb),
    (29, 'messen.kreisberechnung', 626, 18, $auf$[{"l": "umfang", "t": "umfang", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Rad hat den Durchmesser 50 cm. Rechne mit π ≈ 3,14. Der Umfang des Rades ist ① cm. Bei 4 Umdrehungen rollt das Rad ② cm weit. Um 1 570 cm weit zu rollen, braucht das Rad ③ Umdrehungen.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [157, 628, 10]}, "h": "Der Umfang eines Kreises ist π mal Durchmesser. Eine Umdrehung entspricht genau einem Umfang.", "w": "u = 3,14 · 50 = 157 cm. 4 Umdrehungen: 4 · 157 = 628 cm. 1 570 : 157 = 10 Umdrehungen.", "form": "lueckenweg", "zaehlt": "nein", "r": 10627}, {"l": "umfang", "t": "umfang", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Kreis mit dem Durchmesser 10 cm hat den Umfang 31,4 cm. Wie groß ist der Umfang eines Kreises mit dem Durchmesser 70 cm? Rechne mit π ≈ 3,14. Weg A: mit der Formel u = π · d. Weg B: Der Umfang ist proportional zum Durchmesser. Der zweite Durchmesser ist ein Vielfaches des ersten, der Umfang wächst mit demselben Faktor."}, "o": {"wert": 219.8, "einheit": "cm"}, "h": "Beide Wege müssen denselben Umfang ergeben. Bei Weg B brauchst du zuerst den Faktor von 10 cm auf 70 cm.", "w": "Weg A: u = 3,14 · 70 = 219,8 cm. Weg B: Faktor 70 : 10 = 7. u = 31,4 · 7 = 219,8 cm.", "form": "zwei_wege", "zaehlt": "ja", "r": 10628}, {"l": "umfang", "t": "umfang", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Band ist 94,2 cm lang. Es wird straff und ohne Überlappung genau einmal um einen kreisrunden Baumstamm gelegt und passt genau. Rechne mit π ≈ 3,14. Welchen Radius hat der Querschnitt des Stamms?"}, "o": {"wert": 15, "einheit": "cm"}, "h": "Das Band ist so lang wie der Umfang des Querschnitts.", "w": "u = 2 · π · r, also r = u : (2 · π) = 94,2 : 6,28 = 15 cm. Probe: 2 · 3,14 · 15 = 94,2.", "form": "umkehren", "zaehlt": "ja", "r": 10629}, {"l": "flaeche", "t": "flaeche", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Kreis hat den Durchmesser 20 cm. Rechne mit π ≈ 3,14. Der Radius ist ① cm. Das Quadrat des Radius ist ② cm². Der Flächeninhalt des Kreises ist ③ cm².", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [10, 100, 314]}, "h": "Die Fläche eines Kreises ist π mal Radius mal Radius. Gegeben ist der Durchmesser.", "w": "r = 20 : 2 = 10 cm. r² = 100 cm². A = 3,14 · 100 = 314 cm².", "form": "lueckenweg", "zaehlt": "nein", "r": 10630}, {"l": "flaeche", "t": "flaeche", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Kreis hat den Radius 10 cm. Rechne mit π ≈ 3,14. Berechne den Flächeninhalt auf zwei Wegen. Weg A: mit der Formel A = π · r². Weg B: Ein Kreis mit dem Radius 1 cm hat den Flächeninhalt 3,14 cm². Der Kreis mit dem Radius 10 cm entsteht daraus durch Vergrößern mit dem Längenfaktor 10. Wende den passenden Flächenfaktor an."}, "o": {"wert": 314, "einheit": "cm²"}, "h": "Beide Wege müssen denselben Flächeninhalt ergeben. Bei Weg B wird nicht nur eine Länge vergrößert.", "w": "Weg A: A = 3,14 · 10² = 314 cm². Weg B: Längenfaktor 10, Flächenfaktor 10² = 100. A = 3,14 · 100 = 314 cm².", "form": "zwei_wege", "zaehlt": "ja", "r": 10631}, {"l": "flaeche", "t": "flaeche", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kreis hat den Durchmesser 12 cm. Kim berechnet den Flächeninhalt mit π ≈ 3,14. Zeile 1: Der Radius ist r = 12 · 2 = 24 cm. Zeile 2: Die Fläche ist A = 3,14 · 24² = 3,14 · 576 = 1 808,64 cm². Zeile 3: Gerundet auf ganze Quadratzentimeter ist das etwa 1 809 cm². In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Wie hängen Durchmesser und Radius zusammen?", "w": "Der Radius ist halb so groß wie der Durchmesser: r = 12 : 2 = 6 cm. Dann ist A = 3,14 · 36 = 113,04 cm². Der erste Fehler steht in Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 10632}, {"l": "exakt", "t": "exakt", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Kreisring liegt zwischen zwei Kreisen mit demselben Mittelpunkt. Der äußere Kreis hat den Radius 9 cm, der innere den Radius 5 cm. Der äußere Kreis hat die Fläche ① · π cm². Der innere Kreis hat die Fläche ② · π cm². Der Kreisring hat die Fläche ③ · π cm².", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [81, 25, 56]}, "h": "Die Fläche eines Kreises ist π mal Radius zum Quadrat. Den Ring erhältst du durch Abziehen.", "w": "Außen: 9² = 81, also 81π cm². Innen: 5² = 25, also 25π cm². Ring: 81π − 25π = 56π cm².", "form": "lueckenweg", "zaehlt": "nein", "r": 10633}, {"l": "exakt", "t": "exakt", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Ein Kreis hat den Flächeninhalt 49π cm². Welcher Wert ist der Flächeninhalt als Dezimalzahl, wenn man mit π ≈ 3,14 rechnet?"}, "a": ["21,98 cm²", "153,86 cm²", "307,72 cm²", "52,14 cm²"], "o": {"index": 1}, "h": "In 49π steht ein Malzeichen zwischen 49 und π. Setze für π die Näherung ein.", "w": "49π bedeutet 49 · π. Mit π ≈ 3,14: 49 · 3,14 = 153,86 cm².", "form": "bruecke", "zaehlt": "ja", "r": 10634}, {"l": "exakt", "t": "exakt", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Kreisring liegt zwischen zwei Kreisen mit demselben Mittelpunkt. Der äußere Kreis hat den Umfang 20π cm, der innere den Umfang 12π cm. Gib den Flächeninhalt des Kreisrings exakt an: A = □ · π cm². Welche Zahl gehört in das Kästchen?"}, "o": {"wert": 64}, "h": "Von den Umfängen kommst du zu den Radien. Der Ring ist der Rest, wenn du den inneren Kreis wegnimmst.", "w": "u = 2π · r. Außen: 20π = 2π · r, also r = 10 cm. Innen: 12π = 2π · r, also r = 6 cm. Ring: π · 10² − π · 6² = 100π − 36π = 64π cm².", "form": "umkehren", "zaehlt": "ja", "r": 10635}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Kreis hat den Radius 3 cm, ein zweiter Kreis den Radius 6 cm. Der erste Kreis hat die Fläche ① · π cm², der zweite ② · π cm². Die zweite Fläche ist ③-mal so groß wie die erste.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [9, 36, 4]}, "h": "Die Fläche eines Kreises ist π mal Radius zum Quadrat. Vergleiche die beiden Flächen mit einer Division.", "w": "A₁ = π · 3² = 9π. A₂ = π · 6² = 36π. 36 : 9 = 4. Der Radius ist 2-mal so groß, die Fläche 4-mal so groß.", "form": "lueckenweg", "zaehlt": "nein", "r": 10636}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt Umfang und Fläche von drei Kreisen mit den Radien 1 cm, 2 cm und 3 cm (π ≈ 3,14). Der Radius wird von 1 cm auf 2 cm verdoppelt. Was passiert mit Umfang und Fläche?", "grafik": {"typ": "tabelle", "kopf": ["Radius", "Umfang", "Fläche"], "zeilen": [["1 cm", "6,28 cm", "3,14 cm²"], ["2 cm", "12,56 cm", "12,56 cm²"], ["3 cm", "18,84 cm", "28,26 cm²"]]}}, "a": ["Der Umfang und die Fläche werden beide doppelt so groß.", "Der Umfang wird viermal so groß, die Fläche doppelt so groß.", "Der Umfang und die Fläche werden beide viermal so groß.", "Der Umfang wird doppelt so groß, die Fläche wird viermal so groß."], "o": {"index": 3}, "h": "Teile in der Tabelle den Wert für r = 2 cm durch den Wert für r = 1 cm, einmal beim Umfang und einmal bei der Fläche.", "w": "Umfang: 12,56 : 6,28 = 2. Fläche: 12,56 : 3,14 = 4. Der Umfang wächst mit dem Radius (Faktor 2), die Fläche mit dem Quadrat des Radius (Faktor 4).", "form": "bruecke", "zaehlt": "ja", "r": 10637}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim untersucht, was mit der Fläche eines Kreises passiert, wenn man den Radius verdoppelt. Zeile 1: Die Fläche eines Kreises mit dem Radius r ist A = π · r². Zeile 2: Mit dem Radius 2r ist die neue Fläche A' = π · (2r)² = π · 2r² = 2πr². Zeile 3: Also ist A' doppelt so groß wie A. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Was bedeutet (2r)²? Probiere es mit r = 1.", "w": "(2r)² = 2r · 2r = 4r². Also ist A' = 4πr², die Fläche wird 4-mal so groß. Probe mit r = 1: A = π, A' = π · 2² = 4π. Der Fehler steckt in Zeile 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 10638}, {"l": "sektor", "t": "sektor", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Kreissektor hat den Radius 12 cm und den Mittelpunktswinkel 90°. Der Sektor ist 1/① des ganzen Kreises. Der ganze Kreis hat die Fläche ② · π cm². Der Sektor hat die Fläche ③ · π cm².", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [4, 144, 36]}, "h": "Der volle Winkel um einen Punkt ist 360°. Der Sektor hat denselben Anteil an der Fläche wie sein Winkel am vollen Winkel.", "w": "360 : 90 = 4, der Sektor ist ein Viertel. Ganzer Kreis: 12² = 144, also 144π cm². Sektor: 144π : 4 = 36π cm².", "form": "lueckenweg", "zaehlt": "nein", "r": 10639}, {"l": "sektor", "t": "sektor", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Scheibenwischer wird als Strecke vom Drehpunkt bis zum Ende des Wischblatts angenommen und ist 40 cm lang. Er schwenkt um 110° und überstreicht dabei einen Kreissektor. Wie groß ist die überstrichene Fläche? Rechne mit π ≈ 3,14 und runde auf ganze cm²."}, "o": {"wert": 1535, "einheit": "cm²"}, "h": "Der Sektor ist ein Anteil des Kreises mit Radius 40 cm. Der Anteil ist Winkel durch 360°.", "w": "Kreisfläche: 3,14 · 40² = 5 024 cm². Anteil: 110 : 360. Sektor: 5 024 · 110 : 360 ≈ 1 535,1 cm². Gerundet 1 535 cm².", "form": "anwenden", "zaehlt": "ja", "r": 10640}, {"l": "sektor", "t": "sektor", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Kreissektor hat den Radius 6 cm und die Bogenlänge 3π cm. Gib seinen Flächeninhalt exakt an: A = □ · π cm². Welche Zahl gehört in das Kästchen?"}, "o": {"wert": 9}, "h": "Die Bogenlänge ist ein Anteil des Umfangs des ganzen Kreises. Derselbe Anteil gilt für die Fläche.", "w": "Umfang des ganzen Kreises: 2π · 6 = 12π cm. Anteil: 3π : 12π = 1/4. Fläche des ganzen Kreises: 36π cm². Sektor: 36π : 4 = 9π cm². Probe: Bogenlänge · Radius : 2 = 3π · 6 : 2 = 9π.", "form": "umkehren", "zaehlt": "ja", "r": 10641}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Eine Fensterform besteht aus einem Rechteck, 8 cm breit und 6 cm hoch. Auf die 8 cm lange Seite ist ein Halbkreis aufgesetzt. Rechne mit π ≈ 3. Das Rechteck hat die Fläche ① cm². Der Halbkreis hat die Fläche ② cm². Die ganze Form hat die Fläche ③ cm².", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [48, 24, 72]}, "h": "Der Durchmesser des Halbkreises ist die aufgesetzte Seite. Berechne zuerst die Fläche eines ganzen Kreises und nimm davon die Hälfte.", "w": "Rechteck: 8 · 6 = 48 cm². Halbkreis: Radius 4 cm, Kreis 3 · 4² = 48, Hälfte 24 cm². Gesamt: 48 + 24 = 72 cm².", "form": "lueckenweg", "zaehlt": "nein", "r": 10642}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Aus einer rechteckigen Platte, 12 cm lang und 8 cm breit, wird in der Mitte ein kreisrundes Loch mit dem Durchmesser 6 cm ausgeschnitten. Das Loch liegt ganz in der Platte. Welcher Term gibt den Flächeninhalt der Platte nach dem Ausschneiden an (in cm²)?"}, "a": ["12 · 8 − π · 3²", "12 · 8 − π · 6²", "12 · 8 − 2 · π · 3", "12 · 8 + π · 3²"], "o": {"index": 0}, "h": "Von der Fläche des Rechtecks wird die Fläche des Lochs abgezogen. Die Fläche des Lochs ist ein Kreis.", "w": "Rechteck: 12 · 8. Loch: Radius 6 : 2 = 3 cm, Fläche π · 3². Rest: 12 · 8 − π · 3² ≈ 96 − 28,3 = 67,7 cm².", "form": "bruecke", "zaehlt": "ja", "r": 10643}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Sportplatz besteht aus einem Rechteck, 100 m lang und 60 m breit. An den beiden schmalen Seiten ist je ein Halbkreis mit dem Durchmesser 60 m angesetzt. Die ganze Fläche soll mit Kunstrasen belegt werden. Der Kunstrasen wird in Rollen zu je 20 m² geliefert. Rechne mit π ≈ 3,14. Wie viele Rollen müssen mindestens bestellt werden?"}, "o": {"wert": 442}, "h": "Berechne zuerst die ganze Fläche des Platzes. Eine angefangene Rolle muss ganz bestellt werden.", "w": "Rechteck: 100 · 60 = 6 000 m². Die zwei Halbkreise ergeben einen Kreis mit r = 30 m: 3,14 · 30² = 2 826 m². Gesamt: 8 826 m². 8 826 : 20 = 441,3. Es müssen 442 Rollen bestellt werden.", "form": "anwenden", "zaehlt": "ja", "r": 10644}]$auf$::jsonb),
    (37, 'trigo.pythagoras', 555, 18, $auf$[{"l": "hypotenuse", "t": "hypotenuse", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Dreieck ABC hat bei C einen rechten Winkel. Es gilt AC = 20 cm und BC = 21 cm. Gesucht ist die Länge der Hypotenuse AB. Das Quadrat über AC hat den Flächeninhalt ① cm², das Quadrat über BC hat ② cm². Beide Quadrate zusammen haben ③ cm². Die Hypotenuse AB ist ④ cm lang.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [400, 441, 841, 29]}, "h": "Die Quadrate über den beiden Katheten ergeben zusammen das Quadrat über der Hypotenuse. Die Seitenlänge erhältst du aus dem Flächeninhalt des Quadrats.", "w": "AC² = 20² = 400. BC² = 21² = 441. AB² = 400 + 441 = 841. AB = √841 = 29 cm.", "form": "lueckenweg", "zaehlt": "nein", "r": 10556}, {"l": "hypotenuse", "t": "hypotenuse", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Dreieck hat bei C einen rechten Winkel. Die Katheten sind 5 cm und 12 cm lang. Berechne die Länge der Hypotenuse auf zwei Wegen. Weg A: Satz des Pythagoras. Weg B: Lege vier Kopien des Dreiecks so um ein Quadrat, dass ein großes Quadrat mit der Seitenlänge 17 cm entsteht (5 cm + 12 cm). In der Mitte bleibt ein Quadrat, dessen Seite die Hypotenuse ist. Seine Fläche ist die Fläche des großen Quadrats minus die Fläche der vier Dreiecke. Wie lang ist die Hypotenuse?"}, "o": {"wert": 13, "einheit": "cm"}, "h": "Beide Wege müssen dieselbe Länge ergeben. Bei Weg B erhältst du zuerst eine Fläche.", "w": "Weg A: c² = 5² + 12² = 25 + 144 = 169, c = 13 cm. Weg B: großes Quadrat 17² = 289 cm², vier Dreiecke 4 · (5 · 12 : 2) = 120 cm². Mittleres Quadrat: 289 − 120 = 169 cm², Seite √169 = 13 cm. Beide Wege führen auf 13 cm.", "form": "zwei_wege", "zaehlt": "ja", "r": 10557}, {"l": "hypotenuse", "t": "hypotenuse", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Der rechteckige Bildschirm eines Fernsehers hat das Seitenverhältnis Breite : Höhe = 16 : 9. Seine Diagonale ist 55 Zoll lang. Es gilt 1 Zoll = 2,54 cm. Wie breit ist der Bildschirm? Gib die Breite in ganzen Zentimetern an und runde erst am Ende."}, "o": {"wert": 122, "einheit": "cm"}, "h": "Breite und Höhe bestehen aus 16 und 9 gleich langen Stücken. Die Diagonale ist die Hypotenuse des Dreiecks aus Breite und Höhe. Rechne zuerst die Diagonale in cm um.", "w": "Diagonale: 55 · 2,54 = 139,7 cm. Ein Stück hat die Länge k: Breite 16k, Höhe 9k. Dann (16k)² + (9k)² = 139,7², also 337 · k² ≈ 19 516,1 und k ≈ 7,61 cm. Breite: 16 · 7,61 ≈ 121,8 cm. Der Bildschirm ist etwa 122 cm breit.", "form": "anwenden", "zaehlt": "ja", "r": 10558}, {"l": "kathete", "t": "kathete", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Dreieck ABC hat bei C einen rechten Winkel. Die Hypotenuse AB ist 26 cm lang, die Kathete AC ist 10 cm lang. Gesucht ist die Kathete BC. Das Quadrat über AB hat den Flächeninhalt ① cm², das Quadrat über AC hat ② cm². Das Quadrat über BC hat ③ cm². Die Kathete BC ist ④ cm lang.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [676, 100, 576, 24]}, "h": "Die beiden Quadrate über den Katheten ergeben zusammen das Quadrat über der Hypotenuse. Ein Summand fehlt dir.", "w": "AB² = 26² = 676. AC² = 10² = 100. BC² = 676 − 100 = 576. BC = √576 = 24 cm.", "form": "lueckenweg", "zaehlt": "nein", "r": 10559}, {"l": "kathete", "t": "kathete", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Über den Seiten eines Dreiecks ABC mit einem rechten Winkel bei C stehen Quadrate. Die Tabelle zeigt die Flächeninhalte von zwei dieser Quadrate. Wie lang ist die Seite AC?", "grafik": {"typ": "tabelle", "kopf": ["Seite", "Lage im Dreieck", "Fläche des Quadrats über der Seite"], "zeilen": [["BC", "Kathete", "144 cm²"], ["AB", "Hypotenuse", "400 cm²"]]}}, "o": {"wert": 16, "einheit": "cm"}, "h": "Die Quadratfläche über der Hypotenuse ist so groß wie die beiden Quadrate über den Katheten zusammen. Aus der Fläche eines Quadrats erhältst du seine Seitenlänge.", "w": "Das Quadrat über AB (Hypotenuse) hat 400 cm². Das Quadrat über AC hat 400 − 144 = 256 cm². Seitenlänge: √256 = 16 cm. Probe: 144 + 256 = 400.", "form": "bruecke", "zaehlt": "ja", "r": 10560}, {"l": "kathete", "t": "kathete", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim berechnet die Kathete b eines Dreiecks mit einem rechten Winkel. Die Hypotenuse ist c = 17 cm, die andere Kathete ist a = 8 cm. Zeile 1: c² = 17² = 289 und a² = 8² = 64. Zeile 2: b² = c² + a² = 289 + 64 = 353. Zeile 3: b = √353 ≈ 18,8 cm. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Welche Seite ist die längste im rechtwinkligen Dreieck? Welches Quadrat ist die Summe der beiden anderen?", "w": "Die Hypotenuse c steht allein: c² = a² + b². Also ist b² = c² − a² = 289 − 64 = 225 und b = 15 cm. Kim hat in Zeile 2 addiert statt subtrahiert.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 10561}, {"l": "umkehrung", "t": "umkehrung", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Dreieck hat die Seitenlängen 10 cm, 11 cm und 15 cm. Ob es einen rechten Winkel hat, prüfst du mit den Quadraten der Seitenlängen. Das Quadrat der Seite 10 cm ist ① cm², das Quadrat der Seite 11 cm ist ② cm². Beide zusammen sind ③ cm². Das Quadrat der längsten Seite ist ④ cm². Der Unterschied zwischen ④ und ③ ist ⑤. Nur bei einem Unterschied von null wäre das Dreieck rechtwinklig.", "schablone": "① = □; ② = □; ③ = □; ④ = □; ⑤ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [100, 121, 221, 225, 4]}, "h": "Die Umkehrung des Satzes von Pythagoras vergleicht zwei Flächen: das Quadrat der längsten Seite und die Summe der Quadrate der beiden kürzeren Seiten.", "w": "10² = 100, 11² = 121, Summe 221. 15² = 225. Unterschied 225 − 221 = 4, nicht null. Das Dreieck hat keinen rechten Winkel.", "form": "lueckenweg", "zaehlt": "nein", "r": 10562}, {"l": "umkehrung", "t": "umkehrung", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Über den drei Seiten eines Dreiecks stehen Quadrate. Die Tabelle zeigt ihre Flächeninhalte. Was stimmt?", "grafik": {"typ": "tabelle", "kopf": ["Seite", "Fläche des Quadrats über der Seite"], "zeilen": [["a", "36 cm²"], ["b", "49 cm²"], ["c", "85 cm²"]]}}, "a": ["Das Dreieck hat einen rechten Winkel. Er liegt gegenüber der Seite mit dem Quadrat 36 cm².", "Das Dreieck hat keinen rechten Winkel, denn 85 ist keine Quadratzahl.", "Das Dreieck hat einen rechten Winkel. Er liegt gegenüber der Seite mit dem Quadrat 85 cm².", "Das Dreieck hat keinen rechten Winkel, denn 36 + 85 ist nicht 49."], "o": {"index": 2}, "h": "Vergleiche die größte Quadratfläche mit der Summe der beiden anderen.", "w": "36 + 49 = 85. Die Summe der beiden kleineren Quadrate ist so groß wie das größte Quadrat. Nach der Umkehrung des Satzes von Pythagoras ist das Dreieck rechtwinklig. Der rechte Winkel liegt der längsten Seite gegenüber, also der Seite mit dem Quadrat 85 cm².", "form": "bruecke", "zaehlt": "ja", "r": 10563}, {"l": "umkehrung", "t": "umkehrung", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim prüft, ob ein Dreieck mit den Seitenlängen 7 cm, 9 cm und 12 cm einen rechten Winkel hat. Zeile 1: Die längste Seite ist 12 cm. Ihr Quadrat ist 12 · 2 = 24. Zeile 2: Die Quadrate der beiden anderen Seiten ergeben zusammen 7² + 9² = 49 + 81 = 130. Zeile 3: 130 ist nicht gleich 24, also hat das Dreieck keinen rechten Winkel. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Wie berechnet man das Quadrat einer Zahl?", "w": "Das Quadrat von 12 ist 12² = 144, nicht 24. Dann vergleicht man 144 mit 130: Beides ist verschieden, das Dreieck hat keinen rechten Winkel. Das Ergebnis stimmt, aber der Fehler steckt in Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 10564}, {"l": "koordinaten", "t": "koordinaten", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Im Koordinatensystem liegen die Punkte A(−2 | 1) und B(7 | 13). Die Einheit auf beiden Achsen ist 1 cm. Der Unterschied der x-Koordinaten von A und B ist ① cm. Der Unterschied der y-Koordinaten ist ② cm. Diese beiden Unterschiede sind die Katheten eines rechtwinkligen Dreiecks, dessen Hypotenuse die Strecke AB ist. Die Strecke AB ist ③ cm lang.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [9, 12, 15]}, "h": "Der Unterschied zweier Koordinaten ist die größere Zahl minus die kleinere Zahl. Vorsicht bei negativen Zahlen.", "w": "x: 7 − (−2) = 9. y: 13 − 1 = 12. AB² = 9² + 12² = 81 + 144 = 225, AB = 15 cm.", "form": "lueckenweg", "zaehlt": "nein", "r": 10565}, {"l": "koordinaten", "t": "koordinaten", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Drohne soll in gerader Linie vom Startpunkt S(3 | 2) zum Landeplatz L(10 | 8) fliegen. Die Punkte stammen aus einem Plan, in dem jede Einheit des Koordinatensystems 100 m in der Wirklichkeit entspricht. Wie lang ist der Flug? Runde auf ganze Meter."}, "o": {"wert": 922, "einheit": "m"}, "h": "Bestimme zuerst die beiden Koordinatenunterschiede. Rechne erst am Schluss in Meter um.", "w": "Unterschiede: 10 − 3 = 7 und 8 − 2 = 6. Abstand im Plan: √(49 + 36) = √85 ≈ 9,22 Einheiten. 9,22 · 100 ≈ 922. Der Flug ist etwa 922 m lang.", "form": "anwenden", "zaehlt": "ja", "r": 10566}, {"l": "koordinaten", "t": "koordinaten", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Die Punkte A(1 | 2) und B(6 | y) haben den Abstand 13 Längeneinheiten voneinander. Es gilt y > 2. Wie groß ist y?"}, "o": {"wert": 14}, "h": "Zeichne die beiden Punkte und ein passendes rechtwinkliges Dreieck. Welche Seiten sind bekannt?", "w": "Unterschied der x-Koordinaten: 6 − 1 = 5. Dann (y − 2)² = 13² − 5² = 169 − 25 = 144, also y − 2 = 12 (wegen y > 2). y = 14. Probe: Abstand √(5² + 12²) = 13.", "form": "umkehren", "zaehlt": "ja", "r": 10567}, {"l": "raum", "t": "raum", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Quader hat die Kantenlängen 8 cm, 9 cm und 12 cm. Die Diagonale e der Grundfläche (8 cm mal 9 cm) hat das Quadrat e² = ① cm². Die Raumdiagonale d bildet mit e und der Kante der Höhe 12 cm ein rechtwinkliges Dreieck. Das Quadrat der Raumdiagonale ist d² = ② cm². Die Raumdiagonale ist ③ cm lang.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [145, 289, 17]}, "h": "Rechne zuerst in der Grundfläche, dann im zweiten Dreieck. Die Quadrate darfst du stehen lassen, bis du am Ende die Wurzel ziehst.", "w": "e² = 8² + 9² = 64 + 81 = 145. d² = e² + 12² = 145 + 144 = 289. d = √289 = 17 cm.", "form": "lueckenweg", "zaehlt": "nein", "r": 10568}, {"l": "raum", "t": "raum", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein quaderförmiger Karton ist innen 60 cm lang, 40 cm breit und 30 cm hoch. Man will einen möglichst langen, geraden, dünnen Stab hineinlegen. Wie lang darf der Stab höchstens sein? Gib die Länge in ganzen Zentimetern an und runde ab."}, "o": {"wert": 78, "einheit": "cm"}, "h": "Der längste Stab liegt auf der Raumdiagonale des Kartons.", "w": "d² = 60² + 40² + 30² = 3 600 + 1 600 + 900 = 6 100. d = √6 100 ≈ 78,1 cm. Der Stab darf höchstens 78 cm lang sein.", "form": "anwenden", "zaehlt": "ja", "r": 10569}, {"l": "raum", "t": "raum", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Quader hat eine quadratische Grundfläche mit der Seitenlänge 4 cm. Seine Raumdiagonale ist 9 cm lang. Wie hoch ist der Quader?"}, "o": {"wert": 7, "einheit": "cm"}, "h": "Skizziere den Quader mit der Raumdiagonale. Suche rechtwinklige Dreiecke, in denen die Diagonale vorkommt.", "w": "d² = 4² + 4² + h². 81 = 16 + 16 + h², also h² = 49 und h = 7 cm. Probe: 16 + 16 + 49 = 81 = 9².", "form": "umkehren", "zaehlt": "ja", "r": 10570}, {"l": "anwendung", "t": "anwendung", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Eine 5 m lange Leiter lehnt an einer senkrechten Hauswand. Ihr Fuß steht auf waagerechtem Boden und ist 3 m von der Wand entfernt. Das Quadrat der Leiterlänge ist ① m². Das Quadrat des Wandabstands ist ② m². Das Quadrat der Höhe, in der die Leiter die Wand berührt, ist ③ m². Die Leiter berührt die Wand in einer Höhe von ④ m.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [25, 9, 16, 4]}, "h": "Leiter, Wand und Boden bilden ein rechtwinkliges Dreieck. Die Leiter ist die längste Seite.", "w": "Leiter: 5² = 25. Abstand: 3² = 9. Höhe²: 25 − 9 = 16. Höhe: √16 = 4 m.", "form": "lueckenweg", "zaehlt": "nein", "r": 10571}, {"l": "anwendung", "t": "anwendung", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Boot fährt vom Hafen aus 9 km genau nach Osten und dann 12 km genau nach Norden. Wie weit ist es dann in gerader Linie vom Hafen entfernt? Berechne es auf zwei Wegen. Weg A: Satz des Pythagoras. Weg B: Das Dreieck mit den Seiten 9 km und 12 km ist ein Vielfaches des rechtwinkligen Dreiecks mit den Seiten 3, 4 und 5. Bestimme den Vervielfältigungsfaktor und daraus die Entfernung. Welche Entfernung in km erhältst du auf beiden Wegen?"}, "o": {"wert": 15, "einheit": "km"}, "h": "Beide Wege müssen dieselbe Entfernung ergeben. Bei Weg B hilft die Frage: Mit welcher Zahl wurde 3 zu 9?", "w": "Weg A: 9² + 12² = 81 + 144 = 225, √225 = 15 km. Weg B: 9 = 3 · 3 und 12 = 3 · 4, der Faktor ist 3. Die Hypotenuse ist 3 · 5 = 15 km.", "form": "zwei_wege", "zaehlt": "ja", "r": 10572}, {"l": "anwendung", "t": "anwendung", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Satteldach hat zwei gleich große, rechteckige Dachflächen. Das Haus ist 12 m breit, das Dach ist 9 m lang. Der First liegt 4,5 m höher als die Oberkanten der Außenwände und genau über der Mitte des Hauses. Wie viele Quadratmeter Dachfläche hat das Dach insgesamt? Der Dachüberstand wird nicht berücksichtigt."}, "o": {"wert": 135, "einheit": "m²"}, "h": "Die Schräge einer Dachfläche ist die Hypotenuse eines rechtwinkligen Dreiecks. Eine Kathete ist die halbe Hausbreite.", "w": "Halbe Breite: 6 m. Schräge: √(6² + 4,5²) = √(36 + 20,25) = √56,25 = 7,5 m. Eine Dachfläche: 7,5 · 9 = 67,5 m². Zwei Dachflächen: 135 m².", "form": "anwenden", "zaehlt": "ja", "r": 10573}]$auf$::jsonb),
    (38, 'trigo.rechtwinklig', 597, 21, $auf$[{"l": "seiten", "t": "seiten", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Im Dreieck ABC ist der Winkel bei C ein rechter Winkel. Die Tabelle zeigt die Längen der drei Seiten. Wie lang ist die Ankathete des Winkels β bei B?", "grafik": {"typ": "tabelle", "kopf": ["Seite", "Länge"], "zeilen": [["AB", "13 cm"], ["BC", "5 cm"], ["AC", "12 cm"]]}}, "a": ["12 cm", "5 cm", "13 cm"], "o": {"index": 1}, "h": "Die Ankathete eines Winkels ist die Kathete, die an diesem Winkel anliegt. Welche Seite verbindet B mit dem rechten Winkel?", "w": "β liegt bei B. Die Kathete BC liegt an β an, sie ist die Ankathete: 5 cm. AC liegt β gegenüber (Gegenkathete, 12 cm). AB liegt dem rechten Winkel gegenüber (Hypotenuse, 13 cm).", "form": "bruecke", "zaehlt": "ja", "r": 10598}, {"l": "seiten", "t": "seiten", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "Eine 3,7 m lange Leiter lehnt an einer senkrechten Wand. Sie berührt die Wand in 3,5 m Höhe. Ihr Fuß steht auf waagerechtem Boden 1,2 m von der Wand entfernt. Der Winkel α liegt zwischen der Leiter und dem Boden. Welche Länge ist die Ankathete von α?"}, "a": ["1,2 m, der Abstand des Leiterfußes von der Wand", "3,5 m, die Höhe, in der die Leiter die Wand berührt", "3,7 m, die Länge der Leiter"], "o": {"index": 0}, "h": "Die Ankathete liegt an α an und ist nicht die längste Seite des Dreiecks aus Leiter, Wand und Boden.", "w": "Der Winkel α ist der Winkel am Leiterfuß. An ihm liegen der Boden (Strecke Fuß–Wand, 1,2 m) und die Leiter. Die Leiter ist die Hypotenuse, der Boden die Ankathete. Die Wand liegt α gegenüber (Gegenkathete, 3,5 m).", "form": "anwenden", "zaehlt": "ja", "r": 10599}, {"l": "seiten", "t": "seiten", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Im Dreieck ABC ist der Winkel bei C ein rechter Winkel. Kim ordnet die Seiten dem Winkel α bei A zu. Zeile 1: Die Hypotenuse ist AB, denn sie liegt dem rechten Winkel gegenüber. Zeile 2: Die Gegenkathete von α ist BC, denn sie liegt α gegenüber. Zeile 3: Die Ankathete von α ist AB, denn sie liegt auch an α an. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Welche beiden Seiten liegen am Winkel α bei A? Welche davon ist keine Kathete?", "w": "Am Winkel α bei A liegen die Seiten AB und AC. AB ist die Hypotenuse. Die Ankathete ist die Kathete, die an α anliegt, also AC. Der Fehler steckt in Zeile 3.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 10600}, {"l": "verhaeltnisse", "t": "verhaeltnisse", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Dreieck ABC hat bei C einen rechten Winkel. Die Gegenkathete BC von α ist 9 cm lang, die Ankathete AC ist 12 cm lang. Die Hypotenuse ist ① cm lang. Ein anderes Dreieck hat denselben Winkel α und einen rechten Winkel. Seine Hypotenuse ist 30 cm lang. Es entsteht durch Strecken mit dem Faktor ②. Die Gegenkathete von α ist in diesem Dreieck ③ cm lang, die Ankathete ④ cm.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [15, 2, 18, 24]}, "h": "Die Verhältnisse der Seiten hängen nur vom Winkel ab, nicht von der Größe des Dreiecks. Vergleiche zuerst die beiden Hypotenusen.", "w": "AB = √(9² + 12²) = √225 = 15 cm. Faktor: 30 : 15 = 2. Gegenkathete: 9 · 2 = 18 cm. Ankathete: 12 · 2 = 24 cm. Das Verhältnis Gegenkathete : Hypotenuse ist in beiden Dreiecken 9 : 15 = 18 : 30.", "form": "lueckenweg", "zaehlt": "nein", "r": 10601}, {"l": "verhaeltnisse", "t": "verhaeltnisse", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt drei rechtwinklige Dreiecke. Gemessen sind jeweils die Gegenkathete des Winkels α und die Hypotenuse. Bei welchen Dreiecken ist der Winkel α gleich groß?", "grafik": {"typ": "tabelle", "kopf": ["Dreieck", "Gegenkathete von α", "Hypotenuse"], "zeilen": [["1", "3 cm", "5 cm"], ["2", "6 cm", "10 cm"], ["3", "8 cm", "12 cm"]]}}, "a": ["Bei Dreieck 2 und Dreieck 3, denn bei beiden unterscheiden sich Hypotenuse und Gegenkathete um 4 cm", "Bei Dreieck 1 und Dreieck 2", "Bei allen drei Dreiecken", "Bei Dreieck 1 und Dreieck 3, weil sich ihre Hypotenusen um 7 cm unterscheiden"], "o": {"index": 1}, "h": "Der Winkel α ist durch das Verhältnis Gegenkathete : Hypotenuse bestimmt. Berechne es für jede Zeile.", "w": "Dreieck 1: 3 : 5 = 0,6. Dreieck 2: 6 : 10 = 0,6. Dreieck 3: 8 : 12 ≈ 0,67. Gleiches Verhältnis heißt gleicher Winkel α: Dreieck 1 und Dreieck 2. Dreieck 3 hat einen größeren Winkel α.", "form": "bruecke", "zaehlt": "ja", "r": 10602}, {"l": "verhaeltnisse", "t": "verhaeltnisse", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Im Dreieck ABC ist der Winkel bei C ein rechter Winkel. Es gilt BC = 8 cm, AC = 15 cm und AB = 17 cm. Kim berechnet cos α für den Winkel α bei A. Zeile 1: cos α ist das Verhältnis Gegenkathete : Hypotenuse. Zeile 2: Die Gegenkathete von α ist BC = 8 cm, die Hypotenuse ist AB = 17 cm. Zeile 3: Also ist cos α = 8 : 17 ≈ 0,47. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Welche Kathete liegt an α an? Welches Verhältnis gehört zum Kosinus?", "w": "Der Kosinus ist das Verhältnis Ankathete : Hypotenuse. Die Ankathete von α ist AC = 15 cm. cos α = 15 : 17 ≈ 0,88. Das Verhältnis 8 : 17 gehört zum Sinus. Der erste Fehler steht in Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 10603}, {"l": "seite", "t": "seite", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Dreieck ABC hat bei C einen rechten Winkel und die Hypotenuse c = 25 cm. Für den Winkel α gilt sin α = 0,8. Die Gegenkathete a ist ① cm lang. Das Quadrat der Ankathete b ist ② cm². Die Ankathete b ist ③ cm lang.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [20, 225, 15]}, "h": "Der Sinus ist das Verhältnis Gegenkathete : Hypotenuse. Stelle um, wenn die Gegenkathete gesucht ist. Die Ankathete bekommst du danach mit dem Satz des Pythagoras.", "w": "a = c · sin α = 25 · 0,8 = 20 cm. b² = c² − a² = 625 − 400 = 225. b = √225 = 15 cm. Probe: cos α = 15 : 25 = 0,6 und 0,6² + 0,8² = 1.", "form": "lueckenweg", "zaehlt": "nein", "r": 10604}, {"l": "seite", "t": "seite", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Dreieck ABC hat bei C einen rechten Winkel. Die Hypotenuse ist c = 12 cm lang, der Winkel α ist 40° groß. Berechne die Gegenkathete a auf zwei Wegen. Weg A: mit dem Sinus von α. Weg B: zuerst die Ankathete b mit dem Kosinus von α, dann a mit dem Satz des Pythagoras (b auf eine Dezimale gerundet verwenden). Runde das Ergebnis auf eine Dezimale. Der Taschenrechner steht auf Gradmaß (DEG)."}, "o": {"wert": 7.7, "einheit": "cm"}, "h": "Beide Wege dürfen sich höchstens in der Rundung unterscheiden. Bei Weg B brauchst du zuerst b.", "w": "Weg A: a = 12 · sin 40° ≈ 7,71 ≈ 7,7 cm. Weg B: b = 12 · cos 40° ≈ 9,19 ≈ 9,2 cm. a² = 12² − 9,2² = 144 − 84,64 = 59,36, a ≈ 7,70 ≈ 7,7 cm.", "form": "zwei_wege", "zaehlt": "ja", "r": 10605}, {"l": "seite", "t": "seite", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Von der Spitze eines 45 m hohen Leuchtturms am Ufer sieht man ein Boot auf dem Wasser unter einem Tiefenwinkel von 20°. Der Tiefenwinkel ist der Winkel zwischen der Waagerechten und der Blickrichtung nach unten. Die Augenhöhe wird nicht beachtet, das Wasser ist eben. Wie weit ist das Boot vom Fußpunkt des Turms entfernt? Runde auf ganze Meter. Der Taschenrechner steht auf Gradmaß (DEG)."}, "o": {"wert": 124, "einheit": "m"}, "h": "Zeichne das rechtwinklige Dreieck aus Turm, Wasserlinie und Blickrichtung. Der Winkel 20° liegt auch am Boot (Wechselwinkel).", "w": "Am Boot ist der Winkel zwischen Wasserlinie und Blickrichtung ebenfalls 20°. Die Turmhöhe 45 m ist die Gegenkathete, gesucht ist die Ankathete. tan 20° = 45 : d, also d = 45 : tan 20° ≈ 123,6 m. Das Boot ist etwa 124 m entfernt.", "form": "anwenden", "zaehlt": "ja", "r": 10606}, {"l": "winkel", "t": "winkel", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Dreieck ABC hat bei C einen rechten Winkel. Es gilt BC = 6 cm, AC = 8 cm und AB = 10 cm. Der Winkel α bei A liegt der Seite BC gegenüber, und es gilt sin α = 0,6. Mit der Umkehrfunktion des Sinus am Taschenrechner (Gradmaß) ist α auf ganze Grad gerundet ① Grad groß. Der Winkel β bei B ist auf ganze Grad gerundet ② Grad groß.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [37, 53]}, "h": "Der Winkel α ist der Winkel, dessen Sinus 0,6 ist. Die Winkel in einem Dreieck ergeben zusammen 180°, und einer davon ist ein rechter Winkel.", "w": "α = sin⁻¹(0,6) ≈ 36,87°, gerundet 37°. β = 90° − α ≈ 90° − 36,87° = 53,13°, gerundet 53°. Probe: cos β = sin α, und sin⁻¹(0,8) ≈ 53,13°.", "form": "lueckenweg", "zaehlt": "nein", "r": 10607}, {"l": "winkel", "t": "winkel", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Dreieck ABC hat bei C einen rechten Winkel. Die Gegenkathete von α ist 5 cm, die Ankathete 12 cm und die Hypotenuse 13 cm lang. Berechne α auf zwei Wegen. Weg A: mit dem Tangens von α. Weg B: mit dem Sinus von α. Runde auf ganze Grad. Der Taschenrechner steht auf Gradmaß (DEG)."}, "o": {"wert": 23, "einheit": "°"}, "h": "Beide Wege müssen denselben Winkel ergeben. Beim Tangens brauchst du die Ankathete, beim Sinus die Hypotenuse.", "w": "Weg A: tan α = 5 : 12, α = tan⁻¹(5 : 12) ≈ 22,62°. Weg B: sin α = 5 : 13, α = sin⁻¹(5 : 13) ≈ 22,62°. Gerundet: 23°.", "form": "zwei_wege", "zaehlt": "ja", "r": 10608}, {"l": "winkel", "t": "winkel", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Dreieck ABC hat bei C einen rechten Winkel. Die Gegenkathete von α ist 3 cm, die Ankathete 4 cm lang. Kim berechnet α in Grad. Zeile 1: tan α = Gegenkathete : Ankathete = 3 : 4 = 0,75. Zeile 2: Gesucht ist der Winkel, dessen Tangens 0,75 ist, also α = tan⁻¹(0,75). Zeile 3: Mit dem Taschenrechner (Bogenmaß, RAD) erhalte ich α ≈ 0,643501°. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "In welcher Einheit soll der Winkel angegeben werden? Auf welche Einstellung muss der Taschenrechner dann stehen?", "w": "Der Taschenrechner muss auf Gradmaß (DEG) stehen. Dann ist α = tan⁻¹(0,75) ≈ 36,9°. Der Rechner stand auf RAD: tan⁻¹(0,75) ≈ 0,643501 rad ≈ 36,87°, die 0,643501 wurden fälschlich als Grad angegeben. Mit DEG ergibt sich 36,87°, oder man rechnet 0,643501 rad mit 180° : π um. Der Fehler steckt in Zeile 3.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 10609}, {"l": "beziehungen", "t": "beziehungen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Für einen spitzen Winkel α gilt sin α = 0,6. Das Hundertfache von sin² α ist ①. Das Hundertfache von cos² α ist ②. Das Hundertfache von cos α ist ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [36, 64, 80]}, "h": "Zwischen Sinus und Kosinus desselben Winkels gibt es eine Beziehung mit Quadraten. Die Beziehung gilt für sin² α und cos² α, nicht für sin α und cos α.", "w": "sin² α = 0,36, also 100 · sin² α = 36. Aus sin² α + cos² α = 1 folgt cos² α = 0,64 und 100 · cos² α = 64. Dann ist (100 · cos α)² = 100 · 64 = 6 400, also 100 · cos α = 80, cos α = 0,8.", "form": "lueckenweg", "zaehlt": "nein", "r": 10610}, {"l": "beziehungen", "t": "beziehungen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Für einen spitzen Winkel α gilt sin α = 0,6. Berechne cos α auf zwei Wegen. Weg A: mit der Beziehung sin² α + cos² α = 1. Weg B: berechne zuerst den Winkel α mit der Umkehrfunktion des Sinus, dann cos α mit dem Taschenrechner. Runde auf zwei Dezimalen. Der Taschenrechner steht auf Gradmaß (DEG)."}, "o": {"wert": 0.8}, "h": "Beide Wege müssen denselben Wert ergeben. Bei Weg A steht am Ende eine Wurzel.", "w": "Weg A: cos² α = 1 − 0,36 = 0,64, cos α = √0,64 = 0,8. Weg B: α = sin⁻¹(0,6) ≈ 36,87°, cos 36,87° ≈ 0,80. Beide Wege: 0,8.", "form": "zwei_wege", "zaehlt": "ja", "r": 10611}, {"l": "beziehungen", "t": "beziehungen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Für einen spitzen Winkel α gilt sin α = 0,5. Kim berechnet cos α. Zeile 1: Es gilt sin² α + cos² α = 1. Zeile 2: Also ist cos α = 1 − sin α = 1 − 0,5 = 0,5. Zeile 3: Dann sind sin α und cos α gleich, also ist α = 45°. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Welche Größen stehen in der Beziehung zwischen Sinus und Kosinus im Quadrat?", "w": "Es gilt cos² α = 1 − sin² α = 1 − 0,25 = 0,75, also cos α = √0,75 ≈ 0,87. Kim lässt auf beiden Seiten die Quadrate weg. Erst cos² α = 1 − sin² α bestimmen, dann für den spitzen Winkel die positive Wurzel ziehen. Der Fehler steckt in Zeile 2; Zeile 3 folgt daraus.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 10612}, {"l": "anwendung", "t": "anwendung", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Drachen hängt an einer 24 m langen, straff gespannten Schnur, die am Boden befestigt ist und mit dem waagerechten Boden einen Winkel von 30° bildet. Es gilt sin 30° = 0,5. Der Drachen ist ① m hoch über dem Boden. Eine 5-mal so lange Schnur bildet denselben Winkel. Dann ist der Drachen ② m hoch. Er ist dann ③ m höher als vorher.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [12, 60, 48]}, "h": "Die Schnur ist die Hypotenuse, die Höhe die Gegenkathete des Winkels am Boden. Berechne die Gegenkathete aus Hypotenuse und Sinus.", "w": "Höhe: 24 · 0,5 = 12 m. Bei der 5-mal so langen Schnur ist die Höhe auch 5-mal so groß: 60 m. Unterschied: 60 − 12 = 48 m.", "form": "lueckenweg", "zaehlt": "nein", "r": 10613}, {"l": "anwendung", "t": "anwendung", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine gerade Rampe ist 5 m lang und überwindet einen Höhenunterschied von 0,6 m. Wie groß ist ihr Neigungswinkel gegen die Waagerechte? Runde auf eine Dezimale. Der Taschenrechner steht auf Gradmaß (DEG)."}, "o": {"wert": 6.9, "einheit": "°"}, "h": "Die Länge der Rampe ist die Hypotenuse, der Höhenunterschied die Gegenkathete des Neigungswinkels.", "w": "sin α = 0,6 : 5 = 0,12. α = sin⁻¹(0,12) ≈ 6,89°. Der Neigungswinkel ist etwa 6,9°.", "form": "anwenden", "zaehlt": "ja", "r": 10614}, {"l": "anwendung", "t": "anwendung", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein senkrechter Mast ist 20 m hoch und steht auf ebenem Boden. Eine Person, deren Augen 1,6 m über dem Boden liegen, soll die Mastspitze unter einem Höhenwinkel von 25° sehen. Der Höhenwinkel ist der Winkel zwischen der Waagerechten durch die Augen und der Blickrichtung. Wie weit vom Fußpunkt des Mastes muss die Person stehen? Runde auf ganze Meter. Der Taschenrechner steht auf Gradmaß (DEG)."}, "o": {"wert": 39, "einheit": "m"}, "h": "Zeichne die Waagerechte durch die Augen. Die Gegenkathete des Winkels 25° ist nicht die ganze Masthöhe. Gesucht ist die Ankathete.", "w": "Die Spitze liegt 20 − 1,6 = 18,4 m über den Augen. tan 25° = 18,4 : d, also d = 18,4 : tan 25° ≈ 39,459 m, auf ganze Meter gerundet 39 m. Probe: 18,4 : 39 ≈ 0,47 und tan 25° ≈ 0,47.", "form": "umkehren", "zaehlt": "ja", "r": 10615}, {"l": "schnittwinkel", "t": "schnittwinkel", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Gerade g hat die Gleichung y = x − 3, die Gerade h hat die Gleichung y = −x + 5. Winkel werden von der positiven x-Achse aus gegen den Uhrzeigersinn gemessen und liegen zwischen 0° und 180°. Der Winkel von g ist ① Grad. Der Winkel von h ist ② Grad. Der Winkel zwischen den beiden Geraden ist ③ Grad.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [45, 135, 90]}, "h": "Die Steigung ist der Tangens des Winkels zur x-Achse. Bei negativer Steigung ist der Winkel größer als ein rechter Winkel.", "w": "tan⁻¹(1) = 45°, also ist der Winkel von g 45°. h hat die Steigung −1: Der Winkel zur x-Achse ist 180° − 45° = 135°. Unterschied: 135° − 45° = 90°. Die Geraden stehen senkrecht aufeinander.", "form": "lueckenweg", "zaehlt": "nein", "r": 10616}, {"l": "schnittwinkel", "t": "schnittwinkel", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Tabelle zeigt Wertepaare einer linearen Funktion. Ihr Graph ist eine Gerade g. Unter welchem Winkel schneidet g die x-Achse? Gib den Winkel zwischen 0° und 90° an, gerundet auf eine Dezimale. Der Taschenrechner steht auf Gradmaß (DEG).", "grafik": {"typ": "tabelle", "kopf": ["x", "0", "2", "4", "6"], "zeilen": [["y", "1", "2", "3", "4"]]}}, "o": {"wert": 26.6, "einheit": "°"}, "h": "Aus der Tabelle bekommst du die Steigung. Die Steigung ist der Tangens des Winkels zur x-Achse.", "w": "Steigung: (y₂ − y₁) : (x₂ − x₁) = (3 − 1) : (4 − 0) = 0,5. tan α = 0,5, α = tan⁻¹(0,5) ≈ 26,57°. Der Winkel ist etwa 26,6°.", "form": "bruecke", "zaehlt": "ja", "r": 10617}, {"l": "schnittwinkel", "t": "schnittwinkel", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Die Gerade h geht durch den Punkt Q(1 | 2) und steigt von links nach rechts. Sie schneidet die x-Achse unter einem Winkel von 35°. Auch der Punkt P(6 | y) liegt auf h. Wie groß ist y? Runde auf eine Dezimale. Der Taschenrechner steht auf Gradmaß (DEG)."}, "o": {"wert": 5.5}, "h": "Von Q nach P gehst du 5 Einheiten nach rechts. Die Steigung ist der Tangens des Winkels zur x-Achse.", "w": "Steigung m = tan 35° ≈ 0,70. Von Q nach P: 5 Einheiten nach rechts, also 5 · 0,70 ≈ 3,50 nach oben. y = 2 + 3,50 ≈ 5,5. Probe: (5,5 − 2) : 5 = 0,7 und tan 35° ≈ 0,70.", "form": "umkehren", "zaehlt": "ja", "r": 10618}]$auf$::jsonb),
    (65, 'raum.pyramide_kegel_kugel', 563, 21, $auf$[{"l": "pyr_volumen", "t": "pyr_volumen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Eine gerade Pyramide hat als Grundfläche ein Quadrat mit der Kantenlänge 6 cm. Die Pyramide ist 8 cm hoch. Die Grundfläche ist ① cm² groß. Grundfläche mal Höhe ergibt ② cm³. Das Volumen der Pyramide ist ③ cm³.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [36, 288, 96]}, "h": "Das Volumen einer Pyramide ist nur ein Teil des Volumens eines Prismas mit gleicher Grundfläche und gleicher Höhe.", "w": "G = 6 · 6 = 36 cm². G · h = 36 · 8 = 288 cm³. Eine Pyramide fasst ein Drittel davon: V = 288 : 3 = 96 cm³.", "form": "lueckenweg", "zaehlt": "nein", "r": 10564}, {"l": "pyr_volumen", "t": "pyr_volumen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Zelt hat die Form einer geraden Pyramide mit quadratischer Grundfläche. Die Grundkante ist 3 m lang, die Zeltspitze liegt 2,4 m über dem Boden. Wie viele Kubikmeter Luft sind im Zelt?"}, "o": {"wert": 7.2, "einheit": "m³"}, "h": "Die Grundfläche ist ein Quadrat. Die Höhe der Spitze über dem Boden ist die Körperhöhe.", "w": "G = 3 · 3 = 9 m². V = 9 · 2,4 : 3 = 7,2 m³. Im Zelt sind 7,2 m³ Luft.", "form": "anwenden", "zaehlt": "ja", "r": 10565}, {"l": "pyr_volumen", "t": "pyr_volumen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine gerade Pyramide hat eine quadratische Grundfläche. Ihr Volumen beträgt 108 cm³ und ihre Höhe 9 cm. Wie lang ist eine Kante der Grundfläche?"}, "o": {"wert": 6, "einheit": "cm"}, "h": "Das Volumen hängt von Grundfläche und Höhe ab. Überlege, wie du von V zurück zur Kantenlänge kommst.", "w": "G = 3 · V : h = 3 · 108 : 9 = 36 cm². Kante: √36 = 6 cm. Probe: 36 · 9 : 3 = 108.", "form": "umkehren", "zaehlt": "ja", "r": 10566}, {"l": "pyr_oberflaeche", "t": "pyr_oberflaeche", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Eine gerade Pyramide hat als Grundfläche ein Quadrat mit der Kantenlänge 10 cm. Die vier Seitenflächen sind gleich große Dreiecke. Die Höhe eines solchen Dreiecks, gemessen von der Grundkante bis zur Spitze, ist 13 cm. Die Grundfläche ist ① cm² groß. Ein Seitendreieck hat ② cm². Die vier Seitendreiecke zusammen haben ③ cm². Die Oberfläche ist ④ cm².", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [100, 65, 260, 360]}, "h": "Die Oberfläche besteht aus der Grundfläche und dem Mantel. Der Mantel besteht aus allen Seitendreiecken.", "w": "G = 100 cm². Ein Dreieck: 10 · 13 : 2 = 65 cm². Vier Dreiecke: 4 · 65 = 260 cm². O = 100 + 260 = 360 cm².", "form": "lueckenweg", "zaehlt": "nein", "r": 10567}, {"l": "pyr_oberflaeche", "t": "pyr_oberflaeche", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt alle Teile des Netzes einer geraden Pyramide mit quadratischer Grundfläche. Wie groß ist die Oberfläche der Pyramide?", "grafik": {"typ": "tabelle", "kopf": ["Teil des Netzes", "Anzahl", "Fläche je Stück"], "zeilen": [["Quadrat (Grundfläche)", "1", "64 cm²"], ["Dreieck (Seitenfläche)", "4", "40 cm²"]]}}, "a": ["104 cm²", "160 cm²", "224 cm²", "384 cm²"], "o": {"index": 2}, "h": "Rechne für jede Zeile Anzahl mal Fläche je Stück und addiere.", "w": "Quadrat: 1 · 64 = 64 cm². Dreiecke: 4 · 40 = 160 cm². O = 64 + 160 = 224 cm².", "form": "bruecke", "zaehlt": "ja", "r": 10568}, {"l": "pyr_oberflaeche", "t": "pyr_oberflaeche", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Eine gerade Pyramide hat ein Quadrat mit der Kantenlänge 6 cm als Grundfläche. Die Höhe eines Seitendreiecks (von der Grundkante bis zur Spitze) ist 5 cm. Kim berechnet die Oberfläche. Zeile 1: Grundfläche: 6 · 6 = 36 cm². Zeile 2: Ein Seitendreieck: 6 · 5 : 2 = 15 cm². Zeile 3: Oberfläche: Grundfläche plus ein Seitendreieck, also 36 + 15 = 51 cm². In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Wie viele Seitendreiecke hat eine Pyramide mit quadratischer Grundfläche?", "w": "Die Pyramide hat vier Seitendreiecke. O = 36 + 4 · 15 = 36 + 60 = 96 cm². Der Fehler steckt in Zeile 3.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 10569}, {"l": "kegel_volumen", "t": "kegel_volumen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein gerader Kegel hat den Radius 3 cm und die Höhe 10 cm. Die Grundfläche ist ① · π cm² groß. Ein Zylinder mit derselben Grundfläche und derselben Höhe hat das Volumen ② · π cm³. Das Volumen des Kegels ist ③ · π cm³.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [9, 90, 30]}, "h": "Die Grundfläche ist ein Kreis. Ein Kegel fasst nur einen Teil von dem Zylinder mit gleicher Grundfläche und Höhe.", "w": "G = π · 3² = 9π cm². Zylinder: 9π · 10 = 90π cm³. Kegel: ein Drittel davon, 90π : 3 = 30π cm³.", "form": "lueckenweg", "zaehlt": "nein", "r": 10570}, {"l": "kegel_volumen", "t": "kegel_volumen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Sandhaufen hat die Form eines geraden Kegels. Sein Durchmesser am Boden ist 3 m, seine Höhe ist 1,2 m. Rechne mit π ≈ 3,14. Wie viele Kubikmeter Sand sind das? Gib das Ergebnis ohne Rundung an."}, "o": {"wert": 2.826, "einheit": "m³"}, "h": "Der Radius ist halb so groß wie der Durchmesser.", "w": "r = 3 : 2 = 1,5 m. V = 3,14 · 1,5² · 1,2 : 3 = 3,14 · 2,25 · 0,4 = 2,826 m³.", "form": "anwenden", "zaehlt": "ja", "r": 10571}, {"l": "kegel_volumen", "t": "kegel_volumen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein gerader Kegel ist 12 cm hoch und hat das Volumen 113,04 cm³. Rechne mit π ≈ 3,14. Wie groß ist der Radius seiner Grundfläche?"}, "o": {"wert": 3, "einheit": "cm"}, "h": "Das Volumen hängt von Radius und Höhe ab. Überlege, welche Größe gesucht ist und wie du von V dorthin zurückkommst.", "w": "r² = 3 · V : (π · h) = 339,12 : 37,68 = 9. Also r = 3 cm. Probe: 3,14 · 9 · 12 : 3 = 113,04.", "form": "umkehren", "zaehlt": "ja", "r": 10572}, {"l": "kegel_mantel", "t": "kegel_mantel", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein gerader Kegel hat den Radius 5 cm und die Höhe 12 cm. Das Quadrat der Mantellinie s ist ① cm². Die Mantellinie s ist ② cm lang. Die Mantelfläche ist ③ · π cm² groß.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [169, 13, 65]}, "h": "Radius, Höhe und Mantellinie bilden ein rechtwinkliges Dreieck. Die Mantelfläche ist π mal Radius mal Mantellinie.", "w": "s² = 5² + 12² = 25 + 144 = 169. s = 13 cm. M = π · r · s = π · 5 · 13 = 65π cm².", "form": "lueckenweg", "zaehlt": "nein", "r": 10573}, {"l": "kegel_mantel", "t": "kegel_mantel", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein gerader Kegel hat den Radius 3 cm und die Mantellinie 5 cm. Gib die Mantelfläche in der Form M = □ · π cm² an. Welche Zahl gehört in das Kästchen? Rechne auf zwei Wegen. Weg A: mit der Formel M = π · r · s. Weg B: Der abgewickelte Mantel ist ein Kreissektor mit dem Radius s. Seine Bogenlänge ist der Umfang des Grundkreises. Die Fläche des Sektors ist Bogenlänge mal Radius geteilt durch 2."}, "o": {"wert": 15}, "h": "Beide Wege müssen dieselbe Zahl ergeben. Bei Weg B ist die Bogenlänge ein Vielfaches von π.", "w": "Weg A: M = π · 3 · 5 = 15π cm². Weg B: Bogenlänge = 2π · 3 = 6π cm. Sektorfläche = 6π · 5 : 2 = 15π cm². Beide Wege: 15.", "form": "zwei_wege", "zaehlt": "ja", "r": 10574}, {"l": "kegel_mantel", "t": "kegel_mantel", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein gerader Kegel hat den Radius 6 cm und die Höhe 8 cm. Kim berechnet die Oberfläche des Kegels, also Mantel und Grundfläche. Zeile 1: Mantellinie: s² = 6² + 8² = 100, also s = 10 cm. Zeile 2: Mantel: M = π · r · s = π · 6 · 10 = 60π cm². Zeile 3: Oberfläche: O = M + G = 60π + π · 6 · 2 = 72π cm². In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Wie berechnet man die Fläche eines Kreises mit dem Radius 6 cm?", "w": "Die Grundfläche ist π · r² = π · 36 = 36π cm², nicht π · 6 · 2. O = 60π + 36π = 96π cm². Der Fehler steckt in Zeile 3.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 10575}, {"l": "kugel", "t": "kugel", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Eine Kugel hat den Radius 6 cm. Das Quadrat des Radius ist ① cm². Die Oberfläche ist ② · π cm². Das Volumen ist ③ · π cm³.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [36, 144, 288]}, "h": "Die Oberfläche einer Kugel ist 4 mal π mal Radius zum Quadrat. Das Volumen ist vier Drittel mal π mal Radius hoch drei. Mit der Oberfläche geht es kürzer: V = O · r : 3.", "w": "r² = 36. O = 4π · 36 = 144π cm². V = 4/3 · π · 6³ = 4/3 · 216π = 288π cm³. Kontrolle: 144π · 6 : 3 = 288π.", "form": "lueckenweg", "zaehlt": "nein", "r": 10576}, {"l": "kugel", "t": "kugel", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Eine Kugel hat den Radius 3 cm. Gib ihr Volumen in der Form V = □ · π cm³ an. Welche Zahl gehört in das Kästchen? Rechne auf zwei Wegen. Weg A: mit der Formel V = 4/3 · π · r³. Weg B: Berechne das Volumen eines Zylinders mit dem Radius 3 cm und der Höhe 6 cm. Ziehe davon die Volumina von zwei Kegeln ab. Beide Kegel haben den Radius 3 cm und die Höhe 3 cm, ihre Spitzen liegen im Mittelpunkt des Zylinders, ihre Grundflächen sind Boden und Deckel. Der Rest hat dasselbe Volumen wie die Kugel, weil in jeder Höhe der Querschnitt des Rests (ein Kreisring) denselben Flächeninhalt hat wie der Querschnitt der Kugel (eine Kreisscheibe)."}, "o": {"wert": 36}, "h": "Beide Wege müssen dieselbe Zahl ergeben. Bei Weg B rechnest du das Volumen des Zylinders und das der beiden Kegel jeweils in Vielfachen von π.", "w": "Weg A: V = 4/3 · π · 27 = 36π cm³. Weg B: Zylinder: π · 3² · 6 = 54π. Ein Kegel: π · 3² · 3 : 3 = 9π, zwei Kegel 18π. Rest: 54π − 18π = 36π cm³. Beide Wege: 36.", "form": "zwei_wege", "zaehlt": "ja", "r": 10577}, {"l": "kugel", "t": "kugel", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine Kugel hat die Oberfläche 324π cm². Gib ihr Volumen in der Form V = □ · π cm³ an. Welche Zahl gehört in das Kästchen?"}, "o": {"wert": 972}, "h": "Welche Größe der Kugel kannst du aus der Oberfläche bestimmen? Was brauchst du dann für das Volumen?", "w": "4 · r² = 324, also r² = 81 und r = 9 cm. V = 4/3 · π · 9³ = 4/3 · 729π = 972π cm³.", "form": "umkehren", "zaehlt": "ja", "r": 10578}, {"l": "sachkontext", "t": "sachkontext", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Eine Eiswaffel hat die Form eines geraden Kegels mit dem Radius 3 cm und der Höhe 9 cm. Auf der Öffnung liegt eine halbe Eiskugel mit demselben Radius. Rechne mit π ≈ 3. Das Volumen des Kegels ist ① cm³. Das Volumen der halben Kugel ist ② cm³. Zusammen sind das ③ cm³.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [81, 54, 135]}, "h": "Das Volumen der Waffel ist das Volumen eines Kegels. Eine halbe Kugel ist die Hälfte einer ganzen Kugel.", "w": "Kegel: V = 3 · 3² · 9 : 3 = 81 cm³. Ganze Kugel: 4/3 · 3 · 3³ = 108 cm³, halbe Kugel: 54 cm³. Zusammen: 81 + 54 = 135 cm³.", "form": "lueckenweg", "zaehlt": "nein", "r": 10579}, {"l": "sachkontext", "t": "sachkontext", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein kugelförmiger Wassertank hat den Innendurchmesser 2 m. Wie groß ist das Fassungsvermögen des Tanks in Litern? Rechne mit π ≈ 3,14 und 1 m³ = 1 000 Liter. Runde das Ergebnis auf ganze Liter."}, "o": {"wert": 4187, "einheit": "Liter"}, "h": "Der Radius ist halb so groß wie der Durchmesser. Rechne das Volumen zuerst in m³, dann in Liter.", "w": "r = 1 m. V = 4/3 · 3,14 · 1³ ≈ 4,1867 m³. In Liter: 4,1867 · 1 000 ≈ 4 187 l. Es passen etwa 4 187 Liter hinein.", "form": "anwenden", "zaehlt": "ja", "r": 10580}, {"l": "sachkontext", "t": "sachkontext", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine Wachskugel mit dem Radius 6 cm wird vollständig eingeschmolzen. Aus dem Wachs wird ein gerader Kegel mit dem Radius 6 cm gegossen. Das Volumen bleibt dabei gleich. Wie hoch ist der Kegel?"}, "o": {"wert": 24, "einheit": "cm"}, "h": "Beim Einschmelzen und Neugießen ändert sich das Volumen nicht.", "w": "Kugel: V = 4/3 · π · 6³ = 288π cm³. Kegel: π · 6² · h : 3 = 12π · h. Aus 12π · h = 288π folgt h = 24 cm.", "form": "umkehren", "zaehlt": "ja", "r": 10581}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Eine gerade Pyramide hat als Grundfläche ein Quadrat mit der Kantenlänge 3 cm und ist 6 cm hoch. Ihr Volumen ist ① cm³. Eine zweite Pyramide hat dieselbe Höhe, aber ein Quadrat mit der Kantenlänge 6 cm als Grundfläche. Ihr Volumen ist ② cm³. Das Volumen der zweiten Pyramide ist ③-mal so groß wie das der ersten.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [18, 72, 4]}, "h": "Rechne beide Volumina aus und vergleiche sie mit einer Division. Die Grundkante wird bei der Grundfläche quadriert.", "w": "V₁ = 3 · 3 · 6 : 3 = 18 cm³. V₂ = 6 · 6 · 6 : 3 = 72 cm³. 72 : 18 = 4. Die Kante wurde verdoppelt, das Volumen wurde 4-mal so groß.", "form": "lueckenweg", "zaehlt": "nein", "r": 10582}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt das Volumen von drei Kugeln (mit dem genauen Wert von π berechnet und auf zwei Dezimalstellen gerundet). Wie hängt das Volumen vom Radius ab?", "grafik": {"typ": "tabelle", "kopf": ["Radius", "Volumen"], "zeilen": [["1 cm", "4,19 cm³"], ["2 cm", "33,51 cm³"], ["3 cm", "113,10 cm³"]]}}, "a": ["Verdoppelt man den Radius, wird das Volumen doppelt so groß.", "Verdoppelt man den Radius, wird das Volumen 4-mal so groß.", "Verdoppelt man den Radius, wird das Volumen 8-mal so groß.", "Verdoppelt man den Radius, wird das Volumen 6-mal so groß."], "o": {"index": 2}, "h": "Teile das Volumen bei r = 2 cm durch das Volumen bei r = 1 cm. Teile auch das Volumen bei r = 3 cm durch das bei r = 1 cm.", "w": "33,51 : 4,19 ≈ 8 und 113,10 : 4,19 ≈ 27. Die Faktoren sind 2³ und 3³. Das Volumen wächst mit der dritten Potenz des Radius.", "form": "bruecke", "zaehlt": "ja", "r": 10583}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim vergleicht einen geraden Kegel mit einem geraden Zylinder. Beide haben denselben Radius und dieselbe Höhe. Der Zylinder hat den Radius 3 cm und die Höhe 5 cm. Zeile 1: Der Kegel hat die Hälfte des Volumens des Zylinders. Zeile 2: Das Volumen des Zylinders ist V = π · 3² · 5 = 45π cm³. Zeile 3: Also hat der Kegel das Volumen 22,5π cm³. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Wie viele Kegel mit gleichem Radius und gleicher Höhe passen in Volumen genau in einen Zylinder?", "w": "Der Kegel hat ein Drittel des Volumens des Zylinders, nicht die Hälfte: 45π : 3 = 15π cm³. Der erste Fehler steht in Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 10584}]$auf$::jsonb),
    (311, 'messen.prisma_zylinder_teil2', 426, 3, $auf$[{"l": "cavalieri", "t": "cavalieri", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein schiefes Prisma hat als Grundfläche ein Rechteck mit den Seiten 4 cm und 5 cm. Seine schräge Seitenkante ist 10 cm lang. Der senkrechte Abstand zwischen Grund- und Deckfläche beträgt 8 cm. Die Grundfläche ist ① cm² groß. Das Volumen des Prismas ist ② cm³. Würde man fälschlich mit der Länge der Seitenkante rechnen, käme ein um ③ cm³ größeres Volumen heraus.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [20, 160, 40]}, "h": "Nach dem Prinzip von Cavalieri hat ein schiefes Prisma dasselbe Volumen wie ein gerades Prisma mit gleicher Grundfläche und gleicher senkrechter Höhe.", "w": "G = 4 · 5 = 20 cm². Mit der senkrechten Höhe: V = 20 · 8 = 160 cm³. Mit der Seitenkante käme 20 · 10 = 200 cm³ heraus, das sind 200 − 160 = 40 cm³ zu viel.", "form": "lueckenweg", "zaehlt": "nein", "r": 10427}, {"l": "cavalieri", "t": "cavalieri", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "30 quadratische Holzplatten mit der Kantenlänge 20 cm und der Dicke 1 cm werden zu einem Stapel aufgeschichtet. Jede Platte ist gegen die darunterliegende leicht verschoben, sodass der Stapel schief steht. Alle Platten liegen waagerecht. Wie groß ist das Volumen des Stapels in cm³?"}, "o": {"wert": 12000, "einheit": "cm³"}, "h": "Jede Platte hat dasselbe Volumen, egal wie sie verschoben ist. Wie hoch ist der Stapel senkrecht gemessen?", "w": "Der Stapel ist 30 · 1 = 30 cm hoch. Nach Cavalieri ist sein Volumen wie bei einem geraden Stapel: V = 20 · 20 · 30 = 12 000 cm³. Das ist auch 30 Platten mit je 400 cm³.", "form": "anwenden", "zaehlt": "ja", "r": 10428}, {"l": "cavalieri", "t": "cavalieri", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein schiefes Prisma hat als Grundfläche ein Rechteck, das 9 cm lang ist. Der senkrechte Abstand zwischen Grund- und Deckfläche ist 7 cm, die schräge Seitenkante ist 10 cm lang. Das Volumen des Prismas beträgt 252 cm³. Wie breit ist das Rechteck der Grundfläche?"}, "o": {"wert": 4, "einheit": "cm"}, "h": "Das Volumen eines schiefen Prismas ist Grundfläche mal senkrechte Höhe. Die Grundfläche ist ein Rechteck aus Länge und Breite.", "w": "G = V : h = 252 : 7 = 36 cm². Breite = G : Länge = 36 : 9 = 4 cm. Probe: 9 · 4 · 7 = 252. Die Seitenkante von 10 cm ist nicht die Höhe und wird nicht gebraucht.", "form": "umkehren", "zaehlt": "ja", "r": 10429}]$auf$::jsonb)
  ) x(id, schluessel, max_r, soll, aufgaben) loop
    if not exists (select 1 from schule.einheit ei join schule.thema th on th.id = ei.thema_id where ei.id = e.id and th.schluessel = e.schluessel) then
      fehler := fehler || ('Einheit ' || e.id || ' ist nicht ' || e.schluessel)::text; continue; end if;
    if (select coalesce(max(reihenfolge), 0) from schule.aufgabe where einheit_id = e.id and pool = 'uebung' and reihenfolge <= e.max_r) <> e.max_r then
      fehler := fehler || ('Einheit ' || e.id || ': Bestand hat sich seit dem Lesen geändert')::text; continue; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.pool = 'uebung' and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x)) then
      fehler := fehler || ('Einheit ' || e.id || ': Reihenfolge-Nummern des Pakets sind schon belegt (Paket schon eingespielt?)')::text; continue; end if;
    if exists (select 1 from jsonb_array_elements(e.aufgaben) x where not exists (select 1 from schule.einheit ei, jsonb_array_elements(ei.inhalt->'etappen') et where ei.id = e.id and et->>'lernziel' = x->>'l')) then
      fehler := fehler || ('Einheit ' || e.id || ': Lernziel unbekannt')::text; continue; end if;
    select count(*) into vorher from schule.aufgabe where einheit_id = e.id;
    n := schule.aufgaben_einfuegen(e.id, e.aufgaben);
    if n <> e.soll or (select count(*) from schule.aufgabe where einheit_id = e.id) <> vorher + e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': ' || n || ' statt ' || e.soll || ' eingefügt')::text; end if;
    if (select count(*) from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung' and a.form is not null and a.zaehlt is not null) <> e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': form/zaehlt nicht übernommen')::text; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung'
               and not coalesce((schule.antwort_bewerten(a, case a.antworttyp when 'zahl' then jsonb_build_object('wert', '0') else '{}'::jsonb end)->>'format_ok') is not null, false)) then
      fehler := fehler || ('Einheit ' || e.id || ': eine neue Aufgabe lässt sich nicht bewerten')::text; end if;
    gesamt := gesamt + n;
  end loop;
  if gesamt <> 108 then fehler := fehler || ('zusammen ' || gesamt || ' statt 108')::text; end if;
  if array_length(fehler, 1) > 0 then raise exception 'Vorrats-Aufgaben ABBRUCH, alles zurückgerollt: %', array_to_string(fehler, ' | '); end if;
end $einspielen$;
select einheit_id, count(*) filter (where pool = 'uebung') as uebungen, count(*) filter (where form is not null) as mit_form from schule.aufgabe where einheit_id in (8, 29, 37, 38, 65, 311) group by 1 order by 1;
